/** A cursed enemy is drawn this much larger, and its traits read like this under its name (DECISIONS #73). */
const CURSED_SCALE = 1.3;

/**
 * Side-view turn-based combat. Phaser only renders: the engine in core/combat
 * owns the rules, and this scene replays its event log as animation.
 */
interface EnemyView {
  slot: number;
  def: Enemy;
  sprite: Phaser.GameObjects.Rectangle | Phaser.GameObjects.Image | Phaser.GameObjects.Sprite;
  x: number; y: number;
  nameText: Phaser.GameObjects.Text;
  hp: HpBar;
  chips: StatusChips;
  stats: StatLine;
  /** Its death has played: the HUD row stays empty from here. */
  slain?: boolean;
  intentBg: Phaser.GameObjects.Rectangle;
  intentHead: Phaser.GameObjects.Text;
  intentText: Phaser.GameObjects.Text;
  intentNum: Phaser.GameObjects.Text;
  postureText: Phaser.GameObjects.Text;
}

/** A thin dark outline for small labels over the backdrop, so they read on the snow too (DECISIONS #80). */
const LABEL_OUTLINE = { stroke: '#0b0f1a', strokeThickness: 3 };

/** Intent panels draw over the fighters (DECISIONS #92); sprites sit at depth 1-2. */
const PANEL_DEPTH = 6;
/** In a duo, how high an enemy's head may reach, so the panels and the target arrow sit above it. */
const DUO_HEAD_TOP = 198;
/** A duo's panel centre never rises above this: its label stays under the HUD's status row (chips at y 70). */
const DUO_PANEL_MIN_Y = 132;

export class CombatScene extends Phaser.Scene {
  private session!: RunSession;
  private encounter!: PendingEncounter;
  /** Primary enemy's definition (slot 0); per-slot defs live in state.enemyDefs. */
  private enemyDef!: Enemy;
  private state!: CombatState;
  /** Enemy slot the next card goes to; tap an enemy to change it (DECISIONS #29). */
  private target = 0;
  private busy = false;
  private fx!: BattleFx;
  /** The effect of the move being played (DECISIONS #59): cast once per target at its first hit or hostile status. */
  private cast: { kind: VfxKind; side: 'player' | 'enemy'; who: number; done: Set<string> } | null = null;

  private playerSprite!: Phaser.GameObjects.Rectangle | Phaser.GameObjects.Image;
  /** One view per enemy slot: sprite, bar, chips and intent panel. */
  private views: EnemyView[] = [];
  private targetArrow!: Phaser.GameObjects.Text;
  private playerHp!: HpBar;
  private playerStats!: StatLine;
  /** HP as the playback has shown it so far; bars never read live state mid-step. */
  private dispHp: { player: number; enemies: number[] } = { player: 0, enemies: [] };
  private hpBefore = 0;
  private playerChips!: StatusChips;
  private roundText!: Phaser.GameObjects.Text;
  private phaseText!: Phaser.GameObjects.Text;
  private pileText!: Phaser.GameObjects.Text;
  private infoPanel: Phaser.GameObjects.GameObject[] = [];
  private infoTimers: Phaser.Time.TimerEvent[] = [];
  private infoDismiss: (() => void) | null = null;
  private banner!: Phaser.GameObjects.Text;
  private hand: Card[] = [];
  /** What the hand looks like at this point of the playback. The engine state is already end-of-round. */
  private displayHand: string[] = [];
  /** Likewise for status chips: a Guard played this turn must show before the enemy's hit consumes it. */
  private dispStatus: { player: Status[]; enemies: Status[][] } = { player: [], enemies: [] };
  private handHint!: Phaser.GameObjects.Text;
  private holdBtn!: Button;
  private redrawBtn?: Button;
  /** The speech bubble each enemy is showing (DECISIONS #83), so a new line replaces the old. */
  private barks = new Map<number, Phaser.GameObjects.GameObject[]>();
  private holdMode = false;
  private handY = 0;
  private px = 0; private py = 0;

  constructor() { super('Combat'); }

  create() {
    this.busy = false;
    this.fx = new BattleFx(this);
    this.cast = null;
    this.hand = [];
    this.displayHand = [];
    this.barks = new Map();
    this.holdMode = false;
    this.session = getSession(this);
    if (!this.session.pendingEncounter) throw new Error('Combat started without an encounter');
    this.encounter = this.session.pendingEncounter;
    this.enemyDef = this.encounter.custom?.[0] ?? getEnemy(this.encounter.enemyId);
    this.hpBefore = this.session.hp;
    this.target = 0;
    this.views = [];
    this.state = createCombat({
      // The training run (DECISIONS #96) deals some fights a set hand, and the hero cannot die there.
      player: { name: this.session.classId, stats: this.session.stats, hp: this.session.hp, deck: this.session.deck, basics: runBasics(this.session), gear: gearOf(this.session.equipment), ...trainingCombat(this.session, this.encounter.nodeId) },
      enemies: this.encounter.custom ?? [this.encounter.enemyId, ...(this.encounter.extra ?? [])],
      rng: this.session.rng.stream('combat'),
      skillUpgrades: this.session.skillUpgrades,
      growth: this.session.skillGrowth,
    });

    this.buildLayout();
    this.cameras.main.fadeIn(200, 11, 15, 26);
    this.syncAll();
    void this.playEvents(this.state.log);
  }

  // ---------------------------------------------------------------- layout

  private buildLayout() {
    const { width: W, height: H } = this.scale.gameSize;
    this.px = W * 0.27; this.py = H * 0.56;
    this.handY = H - 66;
    const n = this.state.enemies.length;
    // One enemy stands at 73%; a duo spreads 62% / 84% with the rear one a touch smaller.
    const slotX = (slot: number) => (n === 1 ? W * 0.73 : slot === 0 ? W * 0.62 : W * 0.84);

    const groundY = this.py + 46;
    const bgKey = backdropKey(this.encounter.tile, this.session.screenIndex, !!this.session.map.dungeon);
    if (this.textures.exists(bgKey)) {
      // backdrop: its ground band starts on the combatants' feet line, sides crop on narrow screens
      const src = this.textures.get(bgKey).getSourceImage() as { width: number; height: number };
      const scale = Math.max(W / src.width, groundY / (src.height * BACKDROP_HORIZON));
      this.add.image(W / 2, groundY, bgKey).setOrigin(0.5, BACKDROP_HORIZON).setScale(scale).setDepth(-3);
      this.add.rectangle(W / 2, groundY + (1 - BACKDROP_HORIZON) * src.height * scale - 1, W, H, backdropGround(bgKey)).setOrigin(0.5, 0).setDepth(-3);
      // dark fades keep the HUD and the hand legible over the art
      const g = this.add.graphics().setDepth(-2);
      g.fillStyle(0x000000, 0.1); g.fillRect(0, 0, W, H);
      g.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0.8, 0.8, 0, 0); g.fillRect(0, 0, W, 140);
      g.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0, 0, 0.75, 0.75); g.fillRect(0, H - 170, W, 170);
    } else {
      this.add.rectangle(W / 2, H * 0.66, W, 2, COLORS.panelEdge); // placeholder ground line
    }

    // combatants: real art when a texture was loaded (see BootScene.ART_FILES), placeholder shapes otherwise
    const heroKey = artKey(this, `hero_${this.session.classId}`);
    const heroIdle = `anim_hero_${this.session.classId}_idle`;
    if (this.anims.exists(heroIdle)) {
      this.playerSprite = this.add.sprite(this.px, this.py + 46, `hero_${this.session.classId}_idle_c`).setOrigin(0.5, 1).setScale(0.5).play(heroIdle);
    } else if (heroKey) {
      // @2x source shown at half size; feet on the ground line the placeholder's bottom edge sat on.
      this.playerSprite = this.add.image(this.px, this.py + 46, heroKey).setOrigin(0.5, 1).setScale(0.5);
    } else {
      this.playerSprite = this.add.rectangle(this.px, this.py, 64, 92, CLASS_COLORS[this.session.classId] ?? COLORS.player);
    }
    for (const def of this.state.enemyDefs) {
      const slot = this.views.length;
      const isBoss = def.archetype === 'boss';
      const esize = isBoss ? 120 : def.tier === 2 ? 92 : 76;
      const ex = slotX(slot);
      const scale = n === 1 || slot === 0 ? 0.5 : 0.44;
      let sprite: EnemyView['sprite'];
      let ey = H * 0.54;
      const enemyKey = artKey(this, def.art ?? `enemy_${def.id}`);
      if (enemyKey) {
        sprite = this.add.image(ex, groundY, enemyKey).setOrigin(0.5, 1).setScale(def.cursed ? scale * CURSED_SCALE : scale);
        // In a duo the panels sit over the heads, so a tall enemy (screen 2, DECISIONS #92) is drawn no
        // taller than the room under them.
        const room = groundY - DUO_HEAD_TOP;
        if (n > 1 && sprite.displayHeight > room) (sprite as Phaser.GameObjects.Image).setScale(sprite.scaleX * (room / sprite.displayHeight));
        if (def.art?.startsWith('hero_')) (sprite as Phaser.GameObjects.Image).setFlipX(true); // a borrowed hero faces the player
        if (def.tint !== undefined) (sprite as Phaser.GameObjects.Image).setTint(def.tint).setAlpha(0.8);
        ey = groundY - sprite.displayHeight / 2;
      } else {
        sprite = this.add.rectangle(ex, ey, esize * scale * 2, esize * scale * 2, isBoss ? COLORS.boss : COLORS.enemy);
        // The still exists but did not load at boot: fetch it now and swap the square out when it lands.
        reloadArt(this, def.art ?? `enemy_${def.id}`, (key) => this.swapEnemyArt(slot, key, groundY, scale, def));
      }
      sprite.setDepth(n - slot); // front enemy over the rear one
      const nameText = this.add.text(ex, groundY + 12, def.name, { ...text.small, ...LABEL_OUTLINE }).setOrigin(0.5, 0);
      const stats = new StatLine(this, ex, groundY + 38, 'center');
      // Tap an enemy to make it the target.
      sprite.setInteractive({ useHandCursor: true });
      sprite.on('pointerup', () => this.setTarget(slot));
      this.views.push({ slot, def, sprite, x: ex, y: ey, nameText, stats } as EnemyView);
    }
    // Stills come alive cheaply: everyone fades in from a step back (the mirror of the death fade),
    // then breathes with a slow scale bob. Frame animation (docs/ART.md) is parked until the loop is fun.
    for (const [s, dir] of [[this.playerSprite, -1] as const, ...this.views.map((v) => [v.sprite, 1] as const)]) {
      const x = s.x;
      s.setAlpha(0).setX(x + 24 * dir);
      this.tweens.add({ targets: s, alpha: 1, x, duration: 420, ease: 'Quad.Out', onComplete: () => { this.breathe(s); this.curseLook(s); } });
    }
    const eq = Object.values(this.session.equipment).filter(Boolean).map((i) => i!.name).join(' · ');
    this.add.text(this.px, this.py + 58, `${this.session.classId} · ${setName(this.session)}${eq ? `\n${eq}` : ''}`, { ...text.small, ...LABEL_OUTLINE, align: 'center' }).setOrigin(0.5, 0);

    // HP bars + status rows: the player's on the left; one per enemy on the right, stacked for a duo.
    const barW = Math.min(300, W * 0.3);
    this.playerHp = new HpBar(this, 24, 40, barW, this.session.classId.toUpperCase(), this.session.stats.maxHp);
    // ATK / DEF (DECISIONS #77): yours leads your status row; an enemy's sits under its name.
    this.playerStats = new StatLine(this, 24, 70);
    this.playerChips = new StatusChips(this, 24, 70);
    // Duo bars sit side by side in the same left-to-right order as the enemies, so each bar is over its owner.
    for (const v of this.views) {
      const ebarW = n === 1 ? barW : Math.min(170, W * 0.18);
      const right = n === 1 ? W - 24 : W - 24 - (n - 1 - v.slot) * (ebarW + 18);
      v.hp = new HpBar(this, right, 40, ebarW, v.def.name.toUpperCase(), v.def.stats.maxHp, true);
      v.chips = new StatusChips(this, right, 70, true);
    }

    // round + phase + piles
    this.roundText = this.add.text(W / 2, 16, '', { ...text.small, fontSize: '13px' }).setOrigin(0.5);
    this.phaseText = this.add.text(W / 2, 40, 'YOUR TURN', { ...text.body, fontSize: '16px', color: COLORS.gold, fontStyle: 'bold' }).setOrigin(0.5);
    this.pileText = this.add.text(W / 2, 60, '', text.mono).setOrigin(0.5);

    // enemy intent panels: above each enemy; a tall boss would push it into the HUD, so then it sits beside him.
    for (const v of this.views) {
      const pw = n === 1 ? 230 : 176, half = pw / 2 - 11;
      const { ix, iy } = this.intentPanelPos(v, n);
      v.intentBg = this.add.rectangle(ix, iy, pw, 64, COLORS.panel, 0.9).setStrokeStyle(2, COLORS.panelEdge).setInteractive({ useHandCursor: true }).setDepth(PANEL_DEPTH);
      v.intentBg.on('pointerup', () => this.explainIntent(v.slot));
      // The panel is a promise, not a state: the enemy does this after your move.
      v.intentHead = this.add.text(ix - half, iy - 34, n === 1 ? 'AFTER YOUR MOVE, IT WILL' : `${v.def.name.toUpperCase()} WILL`, { fontFamily: FONT, fontSize: '10px', color: '#9aa3b8', fontStyle: 'bold', ...LABEL_OUTLINE }).setOrigin(0, 1).setDepth(PANEL_DEPTH);
      v.intentText = this.add.text(ix - half, iy - 10, '', { ...text.body, fontSize: n === 1 ? '14px' : '12px', fontStyle: 'bold', wordWrap: { width: pw - 60 } }).setOrigin(0, 0.5).setDepth(PANEL_DEPTH);
      v.intentNum = this.add.text(ix + half, iy - 10, '', { ...text.h2, fontSize: n === 1 ? '26px' : '22px' }).setOrigin(1, 0.5).setDepth(PANEL_DEPTH);
      v.postureText = this.add.text(ix, iy + 16, '', { ...text.small, fontSize: n === 1 ? text.small.fontSize : '11px' }).setOrigin(0.5).setDepth(PANEL_DEPTH);
    }
    // Target arrow: a gold chevron bobbing over the enemy the next card hits (duos only; a single enemy needs none).
    this.targetArrow = this.add.text(0, 0, '▼', { fontFamily: FONT, fontSize: '26px', color: COLORS.gold, fontStyle: 'bold', stroke: '#000000', strokeThickness: 4 }).setOrigin(0.5, 1).setDepth(8).setVisible(n > 1);
    this.tweens.add({ targets: this.targetArrow, y: '+=6', duration: 500, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
    this.setTarget(0, true);

    // hand hint (shown while recovering or when the hand is empty)
    this.handHint = this.add.text(W / 2, this.handY, '', { ...text.body, color: '#ffd166', fontStyle: 'bold' }).setOrigin(0.5).setDepth(4);
    // Hold back: discard a card to pass the turn (the out for a trap turn).
    this.holdBtn = new Button(this, W - 70, this.handY, 'Hold', () => this.toggleHold(), { width: 100, height: 48, fontSize: '15px', fill: 0x2a2416, edge: 0x8a6a2b });
    // The Earthen Relic (DECISIONS #82): a paid reshuffle, once per fight. Free in Test Mode.
    const cost = redrawCost(this.session.equipment);
    if (cost !== null) this.redrawBtn = new Button(this, W - 70, this.handY - 60, `Reshuffle\n${this.redrawPrice(cost)}`, () => void this.redraw(), { width: 100, height: 52, fontSize: '13px', fill: 0x1d2a1a, edge: 0x8a7a4a });

    // banner for big moments
    this.banner = this.add.text(W / 2, H * 0.3, '', { ...text.title, fontSize: '34px' }).setOrigin(0.5).setAlpha(0).setDepth(60);

    new Button(this, W / 2, H * 0.66 + 22, 'Quit', () => this.quit(), { width: 70, height: 28, fontSize: '12px' }).setDepth(5).setAlpha(0.6);
    if (this.encounter.surprise) void this.surpriseIntro(getEnemy(this.encounter.surprise).name, this.state.enemyDefs[0]!.name);
    // Each enemy that has something to say says it as the fight opens (DECISIONS #83), the front one first.
    this.views.forEach((v, i) => this.time.delayedCall((this.encounter.surprise ? 2000 : 650) + i * 900, () => this.bark(v.slot, 'start')));
  }

  /** A surprise fight (DECISIONS #81): the map showed one enemy and another is here. Cards wait until it is said. */
  private async surpriseIntro(shown: string, actual: string) {
    this.busy = true;
    await wait(this, 450); // the fighters fade in first
    const W = this.scale.gameSize.width;
    void floatText(this, W / 2, this.scale.gameSize.height * 0.3 + 40, `${/^[AEIOU]/i.test(actual) ? 'An' : 'A'} ${actual} was waiting instead.`, '#ffd166', 18, 1300);
    await this.bannerShow(`That's no ${shown}!`);
    this.busy = false;
  }

  // ---------------------------------------------------------------- sync

  private syncChips() {
    this.playerChips.set(this.dispStatus.player, (s) => this.explainStatus(s, 'you'));
    for (const v of this.views) {
      if (v.slain) continue; // a slain enemy's row stays empty once its death has played
      v.chips.set(this.dispStatus.enemies[v.slot] ?? [], (s) => this.explainStatus(s, v.def.name), this.traitChips(v));
    }
    this.syncStats();
  }

  /** A cursed enemy's traits, as chips that last the fight (DECISIONS #78). */
  private traitChips(v: EnemyView) {
    const cursed = (this.state.enemies[v.slot]?.cursed ?? []).map((t) => {
      const info = CURSED_TRAIT_INFO[t];
      return { label: info.label, color: '#ff8a8a', tap: () => this.showInfo(`${info.label} on ${v.def.name}  ·  the whole fight`, info.desc, '#ff8a8a') };
    });
    // Its weaknesses and habits (DECISIONS #83), gold-edged: things to use, not only to fear.
    // One chip, so a duo's two rows still fit: its first trait and how many more; a tap reads them all.
    const info = enemyTraitInfo(this.state.enemies[v.slot]?.traits);
    const own = info.length ? [{ label: info.length > 1 ? `${info[0]!.label} +${info.length - 1}` : info[0]!.label, color: '#f0d890', edge: 0xc9a227, tap: () => this.showInfo(`${v.def.name}: ${info.map((x) => x.label).join(' · ')}`, info.map((x) => `${x.label}: ${x.desc}`).join('\n'), '#f0d890') }] : [];
    return [...cursed, ...own];
  }

  /**
   * A line from the enemy (DECISIONS #83): a speech bubble over its head for a couple of seconds,
   * picked at random from its barks. These play with the story off.
   */
  private bark(slot: number, kind: 'start' | 'rage' | 'death') {
    const v = this.views[slot];
    const lines = v?.def.barks?.[kind];
    if (!v || !lines?.length) return;
    const line = lines[Math.floor(Math.random() * lines.length)]!;
    // A new line replaces whatever it was still saying.
    this.barks.get(slot)?.forEach((p) => p.destroy());
    // Beside its head, toward the open middle of the stage: the intent panel above the head stays readable.
    const sp = v.sprite as unknown as { displayHeight: number; displayWidth: number };
    const right = v.x - sp.displayWidth * 0.32, y = v.y - sp.displayHeight * 0.12;
    const t = this.add.text(right - 12, y, line, { fontFamily: FONT, fontSize: '15px', color: '#1a1200', fontStyle: 'bold', align: 'center', wordWrap: { width: 220 } }).setOrigin(1, 0.5).setDepth(66);
    const bg = this.add.rectangle(right + 0, y, t.width + 24, t.height + 14, 0xfff6dc, 0.96).setOrigin(1, 0.5).setStrokeStyle(2, 0x1a1200).setDepth(65);
    const tail = this.add.triangle(right - 1, y, 0, -7, 0, 7, 12, 0, 0xfff6dc).setOrigin(0, 0.5).setDepth(65);
    const parts = [bg, tail, t];
    this.barks.set(slot, parts);
    for (const p of parts) p.setAlpha(0);
    this.tweens.add({ targets: parts, alpha: 1, duration: 160 });
    this.time.delayedCall(kind === 'death' ? 1500 : 2300, () => { if (!parts[0]!.active) return; this.tweens.add({ targets: parts, alpha: 0, duration: 260, onComplete: () => { parts.forEach((p) => p.destroy()); if (this.barks.get(slot) === parts) this.barks.delete(slot); } }); });
  }

  /** ATK and DEF under each bar, from the statuses playback has shown so far (DECISIONS #77). */
  private syncStats() {
    const p = statRatings(this.state.player.stats, this.dispStatus.player);
    this.playerChips.x = this.playerStats.x + this.playerStats.set(p.atk, p.def) + 14;
    for (const v of this.views) {
      const e = this.state.enemies[v.slot];
      if (!e || e.dead) { v.stats.setVisible(false); continue; }
      const r = statRatings(e.stats, this.dispStatus.enemies[v.slot] ?? []);
      v.stats.set(r.atk, r.def);
    }
  }

  /** Reset the displayed statuses from the engine (end of playback). */
  private snapStatuses() {
    this.dispStatus = { player: this.state.player.statuses.map((s) => ({ ...s })), enemies: this.state.enemies.map((e) => e.statuses.map((s) => ({ ...s }))) };
  }

  private statusList(side: 'player' | 'enemy', who = 0): Status[] {
    if (side === 'player') return this.dispStatus.player;
    return (this.dispStatus.enemies[who] ??= []);
  }
  private dispUpsert(side: 'player' | 'enemy', status: Status, who = 0) {
    const list = this.statusList(side, who);
    const i = list.findIndex((s) => s.id === status.id);
    if (i >= 0) list[i] = status; else list.push(status);
  }
  private dispRemove(side: 'player' | 'enemy', id: Status['id'], who = 0) {
    const kept = this.statusList(side, who).filter((s) => s.id !== id);
    if (side === 'player') this.dispStatus.player = kept; else this.dispStatus.enemies[who] = kept;
  }
  private dispGuardHit(side: 'player' | 'enemy', id: 'guard' | 'ward' = 'guard', who = 0) {
    const list = this.statusList(side, who);
    if (list.some((s) => s.id === 'aegis')) return; // aegis absorbs without being consumed
    const g = list.find((s) => s.id === id);
    if (g) { g.magnitude -= 1; if (g.magnitude <= 0) this.dispRemove(side, id, who); }
  }

  /** Make `slot` the target of the next card and park the arrow over it. Dead slots fall back to the front living one. */
  private setTarget(slot: number, silent = false) {
    const live = this.state.enemies.filter((e) => !e.dead);
    // Nobody left to point at: the arrow goes, rather than hopping back onto a corpse during the win fade.
    if (live.length === 0) { this.targetArrow.setVisible(false); return; }
    const chosen = this.state.enemies[slot] && !this.state.enemies[slot]!.dead ? slot : live[0]!.slot;
    this.target = chosen;
    const v = this.views[chosen];
    if (!v) return;
    this.tweens.killTweensOf(this.targetArrow);
    this.targetArrow.setPosition(v.x, v.y - v.sprite.displayHeight / 2 - 10);
    this.tweens.add({ targets: this.targetArrow, y: '+=6', duration: 500, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
    for (const o of this.views) o.intentBg.setStrokeStyle(2, o.slot === chosen && this.views.length > 1 ? COLORS.goldHex : COLORS.panelEdge);
    // The cards' numbers are against the target, so a retarget redraws them (silent calls come from syncAll, which rebuilds anyway).
    if (!silent && !this.busy) this.rebuildHand();
  }

  /** Tap-to-explain panel for a status or the enemy's intent. Any tap dismisses it. */
  private showInfo(title: string, body: string, color: string) {
    this.hideInfo();
    const { width: W } = this.scale.gameSize;
    const y = 128;
    const bodyT = this.add.text(W / 2, y + 22, body, { ...text.body, fontSize: '15px', wordWrap: { width: Math.min(560, W - 80) }, align: 'center' }).setOrigin(0.5, 0).setDepth(91);
    const h = bodyT.height + 60;
    const bg = this.add.rectangle(W / 2, y + h / 2 - 6, Math.min(600, W - 40), h, 0x0b0f1a, 0.96).setStrokeStyle(2, COLORS.goldHex).setDepth(90);
    const titleT = this.add.text(W / 2, y, title, { ...text.body, fontSize: '15px', color, fontStyle: 'bold' }).setOrigin(0.5, 0).setDepth(91);
    this.infoPanel = [bg, titleT, bodyT];
    // Any tap dismisses (armed a beat later so the opening tap does not), or it fades after a while.
    // Timers and the listener are tracked so a stale one never closes a newer panel.
    const dismiss = () => this.hideInfo();
    this.infoTimers = [
      this.time.delayedCall(50, () => { this.infoDismiss = dismiss; this.input.once('pointerdown', dismiss); }),
      this.time.delayedCall(7000, dismiss),
    ];
  }
  private hideInfo() {
    for (const t of this.infoTimers) t.remove(false);
    this.infoTimers = [];
    if (this.infoDismiss) { this.input.off('pointerdown', this.infoDismiss); this.infoDismiss = null; }
    for (const o of this.infoPanel) o.destroy();
    this.infoPanel = [];
  }
  private explainStatus(s: Status, who: string) {
    const m = STATUS_LABELS[s.id];
    const dur = s.id === 'guard' || s.id === 'ward' ? `${s.magnitude} hit${s.magnitude === 1 ? '' : 's'} left` : s.id === 'burn' ? `${s.magnitude} per round, ${s.turns} round${s.turns === 1 ? '' : 's'} left` : s.id === 'chill' || s.id === 'brace' || s.id === 'scatter' ? 'until it triggers' : s.id === 'stun' ? `${Math.max(0, s.turns - 1)} turn${s.turns - 1 === 1 ? '' : 's'} left` : `${s.turns} round${s.turns === 1 ? '' : 's'} left`;
    this.showInfo(`${m.label} on ${who}  ·  ${dur}`, m.desc, m.color);
  }
  private explainIntent(who = 0) {
    const { intent, predictedDamage, moveName } = currentIntent(this.state, who);
    const status = 'status' in intent ? intent.status : undefined;
    const hits = intent.kind === 'attack' ? intent.hits : 1;
    const tell = POSTURE_TEXT[this.state.enemies[who]!.next.posture] ?? '';
    const drain = intent.kind === 'attack' && !!intent.drain;
    const magic = intent.kind === 'attack' && intent.dmgType === 'magic';
    this.showInfo(`${this.state.enemyDefs[who]!.name}, after your move`, `${describeIntent(intent.kind, moveName, predictedDamage, hits, status, drain, magic)}\n\nThe round after: ${tell.replace('then: ', '')}.`, '#ffb4b4');
  }

  /** A level is a moment: flash, a big banner, and the point can be spent right now (DECISIONS #32). */
  private levelUpFanfare(level: number, points: number, rewards: string[] = []) {
    const { width: W, height: H } = this.scale.gameSize;
    this.cameras.main.flash(260, 255, 220, 120);
    const big = this.add.text(W / 2, H * 0.16, `LEVEL ${level}!`, { ...text.title, fontSize: '46px', color: COLORS.gold, stroke: '#000000', strokeThickness: 8 }).setOrigin(0.5).setDepth(73).setScale(0.2).setAlpha(0);
    this.tweens.add({ targets: big, scale: 1, alpha: 1, duration: 420, ease: 'Back.Out' });
    this.tweens.add({ targets: big, scale: 1.06, duration: 700, yoyo: true, repeat: -1, ease: 'Sine.InOut', delay: 420 });
    // What the level brought (DECISIONS #49): the max HP, then the card or the gold for each level.
    const gift = [`+${rewards.length || 1} max HP`, ...rewards].join('  ·  ');
    this.add.text(W / 2, H * 0.16 + 38, gift, { ...text.body, fontSize: '16px', color: '#ffffff', fontStyle: 'bold', stroke: '#000000', strokeThickness: 4 }).setOrigin(0.5).setDepth(73);
    for (let i = 0; i < 14; i++) {
      const spark = this.add.text(W / 2 + (Math.random() - 0.5) * 60, H * 0.16, '✦', { fontFamily: FONT, fontSize: `${14 + Math.random() * 14}px`, color: i % 2 ? COLORS.gold : '#ffffff' }).setOrigin(0.5).setDepth(72);
      this.tweens.add({ targets: spark, x: spark.x + (Math.random() - 0.5) * 420, y: spark.y + (Math.random() - 0.7) * 220, alpha: 0, angle: 180, duration: 900 + Math.random() * 500, ease: 'Quad.Out', delay: 120, onComplete: () => spark.destroy() });
    }
    const total = getMeta(this).progress[this.session.classId]?.points ?? points;
    new Button(this, W / 2, H * 0.62 + 56, `Spend skill point${total === 1 ? '' : 's'} (${total})`, () => this.scene.start('SkillTree', { classId: this.session.classId, returnTo: 'Reward' }), { width: 260, height: 40, fontSize: '14px', fill: 0x173526, edge: 0x3fbf7a }).setDepth(72);
  }

  private hideIntent(who: number) {
    const v = this.views[who];
    if (!v) return;
    for (const o of [v.intentBg, v.intentHead, v.intentText, v.intentNum, v.postureText]) o.setVisible(false);
  }

  private killerId(): string { return this.state.enemyDefs.find((d) => d.name === this.killerName())?.id ?? this.enemyDef.id; }
  /** The enemy whose hit (or tick) took the last HP; the primary enemy if the log is unclear. */
  private killerName(): string {
    for (let i = this.state.log.length - 1; i >= 0; i--) {
      const e = this.state.log[i]!;
      if ((e.t === 'damage' && e.target === 'player' && !e.blocked) || e.t === 'counter' || (e.t === 'burn' && e.side === 'player')) return this.state.enemyDefs[(e as { who?: number }).who ?? 0]!.name;
    }
    return this.enemyDef.name;
  }

  /** Idle breathing: a slow 2.5% vertical squash on the feet-anchored sprite. Lunges tween x, so the two never fight. */
  /** Where an enemy's intent panel sits: above the sprite, or beside a tall boss that would push it into the HUD. */
  private intentPanelPos(v: EnemyView, n: number): { ix: number; iy: number } {
    const W = this.scale.gameSize.width, pw = n === 1 ? 230 : 176;
    // Beside the enemy only for a lone tall one (a boss): in a duo the rear one's panel would land
    // on the front enemy (DECISIONS #92), so duo panels always sit above their own enemy.
    const tall = n === 1 && v.sprite.displayHeight > 170;
    const ix = tall ? Math.max(W / 2 - 40, v.x - v.sprite.displayWidth / 2 - pw / 2 - 10) : Math.min(W - pw / 2 - 6, v.x);
    // Duos sit the panels a little higher so the target arrow fits between panel and head.
    const iy = tall ? 190 : n === 1 ? Math.max(126, v.y - v.sprite.displayHeight / 2 - 58) : Math.max(DUO_PANEL_MIN_Y, v.y - v.sprite.displayHeight / 2 - 72);
    return { ix, iy };
  }

  /** Replace an enemy's placeholder square with its still once a late load succeeds (see reloadArt). */
  private swapEnemyArt(slot: number, key: string, groundY: number, scale: number, def: Enemy) {
    const v = this.views[slot];
    if (!v || !(v.sprite instanceof Phaser.GameObjects.Rectangle) || !this.scene.isActive()) return;
    const old = v.sprite;
    const img = this.add.image(v.x, groundY, key).setOrigin(0.5, 1).setScale(scale).setDepth(old.depth).setAlpha(old.alpha);
    if (def.art?.startsWith('hero_')) img.setFlipX(true);
    if (def.tint !== undefined) img.setTint(def.tint).setAlpha(0.8);
    img.setInteractive({ useHandCursor: true });
    img.on('pointerup', () => this.setTarget(slot));
    this.tweens.killTweensOf(old);
    old.destroy();
    v.sprite = img;
    v.y = groundY - img.displayHeight / 2;
    // The panel was placed for the square; move it to where the still wants it.
    const { ix, iy } = this.intentPanelPos(v, this.views.length);
    const dx = ix - v.intentBg.x, dy = iy - v.intentBg.y;
    for (const o of [v.intentBg, v.intentHead, v.intentText, v.intentNum, v.postureText]) o.setPosition(o.x + dx, o.y + dy);
    if (this.state.enemies[slot]?.dead) { img.setAlpha(0.15); img.disableInteractive(); return; }
    this.breathe(img);
    if (!this.busy) this.setTarget(this.target, true);
  }

  /**
   * A cursed enemy (DECISIONS #73): larger (set at creation), tinted red, fading out toward its
   * feet, and floating a little off the ground. The fade is per-corner alpha, put on after the
   * fade-in, which tweens a single alpha.
   */
  private curseLook(s: Phaser.GameObjects.Rectangle | Phaser.GameObjects.Image | Phaser.GameObjects.Sprite) {
    const v = this.views.find((x) => x.sprite === s);
    if (!v?.def.cursed || !(s instanceof Phaser.GameObjects.Image) || !s.active) return;
    s.setTint(0xff5a5a);
    s.setAlpha(1, 1, 0.08, 0.08);
    s.y -= 14;
    this.tweens.add({ targets: s, y: s.y - 9, duration: 1700, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
  }

  private breathe(s: Phaser.GameObjects.Rectangle | Phaser.GameObjects.Image | Phaser.GameObjects.Sprite) {
    if (!s.active) return;
    this.tweens.add({ targets: s, scaleY: s.scaleY * 1.025, duration: 1400, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
  }

  private showHp(side: 'player' | 'enemy', delta: number, who = 0) {
    if (side === 'player') {
      this.dispHp.player = Math.max(0, Math.min(this.state.player.stats.maxHp, this.dispHp.player + delta));
      void this.playerHp.set(this.dispHp.player, this.state.player.stats.maxHp);
      return;
    }
    const c = this.state.enemies[who]!, v = this.views[who]!;
    this.dispHp.enemies[who] = Math.max(0, Math.min(c.stats.maxHp, (this.dispHp.enemies[who] ?? c.hp) + delta));
    void v.hp.set(this.dispHp.enemies[who]!, c.stats.maxHp);
  }

  private syncAll() {
    this.dispHp = { player: this.state.player.hp, enemies: this.state.enemies.map((e) => e.hp) };
    void this.playerHp.set(this.state.player.hp, this.state.player.stats.maxHp);
    for (const v of this.views) { const en = this.state.enemies[v.slot]!; if (en.dead) v.hp.setDead(); else void v.hp.set(en.hp, en.stats.maxHp); }
    this.setTarget(this.target, true);
    this.snapStatuses();
    this.syncChips();
    this.roundText.setText(`Round ${this.state.round}  ·  screen ${this.session.screenIndex + 1}`);
    this.pileText.setText(`deck ${this.state.player.deck.length}  ·  hand ${this.state.player.hand.length}  ·  discard ${this.state.player.discard.length}`);
    this.displayHand = this.state.player.hand.slice();
    this.rebuildHand();
  }

  private rebuildHand() {
    for (const c of this.hand) c.destroy();
    this.hand = [];
    const ids = this.displayHand;
    const gap = 12;
    const total = ids.length * CARD_W + (ids.length - 1) * gap;
    const startX = this.scale.gameSize.width / 2 - total / 2 + CARD_W / 2;
    // Each damage card's headline is what the chosen target will take, judged by the statuses the
    // playback has shown so far (the same rule as the chips), so card and chips never disagree (DECISIONS #40).
    const target = resolveTarget(this.state, this.target);
    const shown = (en: typeof target, strip: string[] = []) => ({ ...en, statuses: this.statusList('enemy', en.slot).filter((st) => !strip.includes(st.id)) });
    const shownPlayer = { ...this.state.player, statuses: this.statusList('player') };
    ids.forEach((id, i) => {
      const full = skillInCombat(this.state, id);
      // A branching card shows the side it would take right now (DECISIONS #69); its text keeps both.
      const sk = { ...full, effects: effectsNow(this.state, full, target) };
      const dmg = sk.effects.find((e) => e.type === 'damage');
      let preview: CardPreview | undefined;
      if (dmg && dmg.type === 'damage') {
        // A sweep's headline is the total over every living enemy, each judged by its own statuses,
        // less whatever the card removes before it hits (DECISIONS #48).
        const victims = dmg.targets === 'all' ? this.state.enemies.filter((e) => !e.dead) : [target];
        const strip = sk.effects.flatMap((e) => (e.type === 'strip' ? e.statuses : []));
        const parts = victims.map((v) => previewDamage(shownPlayer, shown(v, strip), dmg));
        preview = { hits: parts.flatMap((p) => p.hits), reasons: [...new Set(parts.flatMap((p) => p.reasons))] };
      }
      const card = new Card(this, startX + i * (CARD_W + gap), this.handY, sk, () => this.act(this.holdMode ? { type: 'hold', index: i } : { type: 'card', index: i, target: this.target }), describeSkill(full, this.state.player.stats), this.state.player.stats, preview);
      // Lunch Break (#69): a card that deals damage waits until Regen is over.
      if (isLocked(this.state, id)) { card.setEnabled(false); card.add(this.add.text(0, 0, 'ON LUNCH BREAK', { ...text.small, fontSize: '11px', color: '#0b0f1a', fontStyle: 'bold', backgroundColor: '#7dff9a', padding: { x: 5, y: 2 } }).setOrigin(0.5)); }
      this.hand.push(card);
    });
  }

  private dropFromDisplay(skill: string) {
    const i = this.displayHand.indexOf(skill);
    if (i >= 0) this.displayHand.splice(i, 1);
  }

  private setInputEnabled(on: boolean) {
    for (const c of this.hand) c.setEnabled(on && !isLocked(this.state, c.skillId));
    this.holdBtn.setEnabled(on);
    this.syncRedraw(on);
    if (!on) this.toggleHold(false);
  }

  /** The reshuffle's price: the relic's gold, nothing in Test Mode. */
  private redrawPrice(cost: number) { return this.session.testMode ? 'free (test)' : `${cost} gold`; }
  private syncRedraw(on: boolean) {
    const cost = redrawCost(this.session.equipment);
    if (!this.redrawBtn || cost === null) return;
    const afford = this.session.testMode || this.session.gold >= cost;
    this.redrawBtn.setEnabled(on && afford && !this.state.redrawUsed);
    this.redrawBtn.setAlpha(this.state.redrawUsed ? 0.35 : afford ? 1 : 0.6);
    this.redrawBtn.label.setText(this.state.redrawUsed ? 'Reshuffled' : `Reshuffle\n${afford ? this.redrawPrice(cost) : `need ${cost} gold`}`);
  }
  /** Pay, shuffle every card back in, and deal a fresh hand (DECISIONS #82). Not a play: the turn goes on. */
  private async redraw() {
    const cost = redrawCost(this.session.equipment);
    if (this.busy || cost === null || this.state.redrawUsed || this.state.outcome !== 'ongoing') return;
    if (!this.session.testMode) { if (this.session.gold < cost) return; this.session.gold -= cost; }
    this.toggleHold(false);
    await this.playEvents(redrawHand(this.state));
  }

  private toggleHold(force?: boolean) {
    this.holdMode = force ?? !this.holdMode;
    this.holdBtn.label.setText(this.holdMode ? 'Cancel' : 'Hold');
    this.handHint.setText(this.holdMode ? (this.state.playsLeft > 1 ? 'tap a card to hold it back (it uses one card)' : 'tap a card to hold it back and pass the turn') : '');
    for (const c of this.hand) c.setAlpha(this.holdMode ? 0.8 : 1);
  }

  /** Recovering (or an empty hand): the turn passes on its own after a beat. */
  private async autoPass() {
    const stunned = isPlayerStunned(this.state);
    const left = stunned ? Math.max(0, (this.state.player.statuses.find((s) => s.id === 'stun')?.turns ?? 1) - 1) : 0;
    this.handHint.setText(stunned ? `Recovering… ${left} turn${left === 1 ? '' : 's'} to go` : this.state.player.hand.length ? 'On lunch break: nothing to play. The turn passes.' : 'No cards. The turn passes.');
    for (const c of this.hand) c.setEnabled(false);
    await wait(this, 900);
    this.handHint.setText('');
    this.act({ type: 'skip' });
  }

  private showIntent(intent: Intent, posture: Posture, predicted: number, moveName: string, who = 0) {
    const v = this.views[who]!;
    const label = intent.kind === 'attack' ? `${moveName}${intent.hits > 1 ? ` x${intent.hits}` : ''}${intent.dmgType === 'magic' ? ' · magic' : ''}${intent.drain ? ' · drains' : ''}`
      : intent.kind === 'guard' ? `${moveName} (guard)`
      : intent.kind === 'debuff' ? `${moveName} → ${STATUS_LABELS[intent.status].label}`
      : intent.kind === 'buff' ? (intent.status === 'brace' ? `${moveName}: counters next hit` : intent.status === 'scatter' ? `${moveName}: halves single hits` : intent.status === 'harden' ? `${moveName}: takes half damage` : `${moveName} (+${intent.status})`)
      : `${moveName} (stagger)`;
    v.intentText.setText(label);
    v.intentNum.setText(intent.kind === 'attack' ? String(predicted) : intent.kind === 'guard' ? '🛡' : '');
    v.postureText.setText(POSTURE_TEXT[posture] ?? '');
  }

  // ---------------------------------------------------------------- actions

  private act(action: PlayerAction) {
    if (this.busy || this.state.outcome !== 'ongoing') return;
    // A coin card (Trickster, #69): the player calls it before it is played.
    if (action.type === 'card' && !action.call) {
      const id = this.state.player.hand[action.index];
      if (id && skillInCombat(this.state, id).effects.some((e) => e.type === 'if' && e.cond.kind === 'coin')) { this.askCoin((call) => this.act({ ...action, call })); return; }
    }
    // A blackjack card (DECISIONS #88): the hand is played out at the table before the card is.
    if (action.type === 'card' && action.bjHits === undefined) {
      const id = this.state.player.hand[action.index];
      if (id && skillInCombat(this.state, id).effects.some((e) => e.type === 'if' && e.cond.kind === 'blackjack')) { this.askBlackjack((bjHits) => this.act({ ...action, bjHits })); return; }
    }
    if (action.type === 'card') this.events.emit('tutorial:play', this.state.player.hand[action.index]);
    const events = step(this.state, action);
    void this.playEvents(events);
  }

  // ---------------------------------------------------------------- training (DECISIONS #96)

  /** The lessons a training fight teaches, each once, as the player's turn opens. */
  private async trainingTurn() {
    const stop = stopIndex(this.session.map, this.encounter.nodeId ?? '');
    const go = (id: LessonId, o: { target?: () => Rect | null; until?: Promise<unknown> } = {}) => trainingLesson(this, id, o);
    const shown = (id: LessonId) => lessonShown(this, id);
    const card = (id: string) => () => boundsOf(this.hand.find((c) => c.skillId === id));
    const played = (id: string) => new Promise<void>((done) => { const on = (k: string) => { if (k === id) { this.events.off('tutorial:play', on); done(); } }; this.events.on('tutorial:play', on); });
    const has = (id: string) => this.state.player.hand.includes(id);
    // Statuses: the first turn that opens with a chip on the hero (the Hex Imp's Weak, usually), where ATK, DEF and the
    // chips share one row. From the duo on, an enemy's chips will do (an enemy's ATK and DEF sit apart, at its feet).
    const live = this.views.filter((v) => !v.slain);
    const chipped = this.statusList('player').length ? 'player' : stop >= 6 ? live.find((v) => this.statusList('enemy', v.slot).length) : undefined;
    if (chipped && !shown('statuses')) {
      const r = chipped === 'player' ? () => around([boundsOf(this.playerStats), boundsOf(this.playerChips)]) : () => around([boundsOf(chipped.chips)]);
      if (!(await go('statuses', { target: r }))) return;
    }
    if (stop === 1 && !shown('guard') && has('defend')) {
      if (!(await go('hand', { target: () => around(this.hand.map(boundsOf)) }))) return;
      if (!(await go('intent', { target: () => this.intentRect(0) }))) return;
      await go('guard', { target: card('defend'), until: played('defend') });
    } else if (stop === 1 && shown('guard') && !shown('attack') && has('attack')) {
      await go('attack', { target: card('attack'), until: played('attack') });
    } else if (stop === 2 && !shown('ward') && has('ward')) {
      await go('ward', { target: card('ward'), until: played('ward') });
    } else if (stop === 2 && shown('ward') && !shown('hold')) {
      await go('hold', { target: () => around(this.hand.map(boundsOf)), until: new Promise((r) => this.events.once('card:peek', r)) });
    } else if (stop === 6 && !shown('duo')) {
      await go('duo', { target: () => around(this.views.flatMap((v) => [boundsOf(v.sprite as unknown as Phaser.GameObjects.Image), this.intentRect(v.slot)])) });
    }
  }
  private intentRect(slot: number): Rect | null {
    const v = this.views[slot];
    return v ? around([boundsOf(v.intentBg), boundsOf(v.intentHead), boundsOf(v.postureText)], 4) : null;
  }

  /** Heads or tails, over the hand; Cancel puts the card back. */
  /**
   * The blackjack table (DECISIONS #88): the dealer stands on 16; you see your two cards and Hit or
   * Stand. A bust ends it. The cards are the ones the play will deal (blackjackHand), so what you see
   * is what lands.
   */
  private askBlackjack(then: (hits: number) => void) {
    const W = this.scale.gameSize.width, H = this.scale.gameSize.height;
    this.setInputEnabled(false);
    const parts: Phaser.GameObjects.GameObject[] = [];
    const close = () => { for (const p of parts) p.destroy(); };
    const cy = H * 0.42;
    parts.push(this.add.rectangle(W / 2, H / 2, W, H, 0x04130b, 0.82).setDepth(60).setInteractive());
    parts.push(this.add.ellipse(W / 2, cy + 10, Math.min(720, W - 60), 300, 0x0f5a32, 1).setStrokeStyle(8, 0x5a3a1a).setDepth(60));
    parts.push(this.add.text(W / 2, cy - 112, `Dealer stands on ${BLACKJACK_BEAT}. Beat it without passing 21.`, { ...text.body, fontSize: '16px', color: '#f5e6b0', fontStyle: 'bold' }).setOrigin(0.5).setDepth(61));
    const cardsLayer: Phaser.GameObjects.GameObject[] = [];
    const totalText = this.add.text(W / 2, cy + 70, '', { ...text.h2, fontSize: '26px', color: '#ffffff', stroke: '#000000', strokeThickness: 4 }).setOrigin(0.5).setDepth(62);
    parts.push(totalText);
    let hits = 0;
    const drawCard = (x: number, y: number, rank: string, suit: string) => {
      const red = suit === '♥' || suit === '♦' ? '#c81e1e' : '#111111';
      const c = this.add.container(x, y).setDepth(62);
      c.add([
        this.add.rectangle(3, 4, 66, 92, 0x000000, 0.35),
        this.add.rectangle(0, 0, 66, 92, 0xfffdf6).setStrokeStyle(2, 0x333333),
        this.add.text(-27, -40, `${rank}\n${suit}`, { fontFamily: 'Arial', fontSize: '15px', color: red, fontStyle: 'bold', align: 'center', lineSpacing: -3 }),
        this.add.text(0, 8, suit, { fontFamily: 'Arial', fontSize: '34px', color: red }).setOrigin(0.5),
      ]);
      return c;
    };
    const show = () => {
      for (const o of cardsLayer) o.destroy();
      cardsLayer.length = 0;
      const hand = blackjackHand(this.state, hits);
      const n = hand.cards.length, gap = 76;
      hand.cards.forEach((c, i) => cardsLayer.push(drawCard(W / 2 - ((n - 1) * gap) / 2 + i * gap, cy - 20, c.rank, c.suit)));
      const bust = hand.total > 21;
      totalText.setText(bust ? `${hand.total}: BUST` : `${hand.total}`).setColor(bust ? '#ff6b6b' : hand.total > BLACKJACK_BEAT ? '#7dff9a' : '#ffffff');
      return bust;
    };
    const finish = () => { close(); for (const o of cardsLayer) o.destroy(); then(hits); };
    const hitBtn = new Button(this, W / 2 - 100, cy + 128, 'Hit', () => {
      hits++;
      if (show()) { hitBtn.setEnabled(false); standBtn.setEnabled(false); this.time.delayedCall(900, finish); }
    }, { width: 150, height: 54, fontSize: '19px', fill: 0x3a2e10, edge: 0xe0b040 }).setDepth(63);
    const standBtn = new Button(this, W / 2 + 100, cy + 128, 'Stand', finish, { width: 150, height: 54, fontSize: '19px', fill: 0x103a22, edge: 0x7dff9a }).setDepth(63);
    parts.push(hitBtn, standBtn);
    show();
  }

  private askCoin(then: (call: 'heads' | 'tails') => void) {
    const W = this.scale.gameSize.width, y = this.handY;
    this.setInputEnabled(false);
    const parts: Phaser.GameObjects.GameObject[] = [];
    const close = () => { for (const p of parts) p.destroy(); };
    parts.push(this.add.rectangle(W / 2, y, W, 150, 0x070a12, 0.85).setDepth(60).setInteractive());
    parts.push(this.add.text(W / 2, y - 48, 'Call it', { ...text.body, fontSize: '18px', color: COLORS.gold, fontStyle: 'bold' }).setOrigin(0.5).setDepth(61));
    const pick = (call: 'heads' | 'tails') => { close(); then(call); };
    parts.push(new Button(this, W / 2 - 120, y + 8, 'Heads', () => pick('heads'), { width: 150, height: 56, fontSize: '18px', fill: 0x3a2e10, edge: 0xe0b040 }).setDepth(61));
    parts.push(new Button(this, W / 2 + 120, y + 8, 'Tails', () => pick('tails'), { width: 150, height: 56, fontSize: '18px', fill: 0x3a2e10, edge: 0xe0b040 }).setDepth(61));
    parts.push(new Button(this, W - 70, y + 8, 'Cancel', () => { close(); this.setInputEnabled(true); }, { width: 100, height: 44, fontSize: '14px' }).setDepth(61));
  }

  private async playEvents(events: CombatEvent[]) {
    this.busy = true;
    this.setInputEnabled(false);
    this.hideInfo();
    // Beats (DECISIONS #47, #64): a sweep's volley and statuses that land together play at once.
    for (const beat of beats(events)) {
      if (beat.lanes.length === 1 && beat.lanes[0]!.length === 1) { const st = beat.lanes[0]![0]!; await this.playEvent(st.e, st.stack); continue; }
      await Promise.all(beat.lanes.map(async (lane) => { for (const st of lane) await this.playEvent(st.e, st.stack); }));
    }
    this.busy = false;
    if (this.state.outcome === 'ongoing') {
      this.syncAll();
      if (isPlayerStunned(this.state) || playableIndices(this.state).length === 0) { void this.autoPass(); return; }
      this.setInputEnabled(true);
      if (this.session.training) void this.trainingTurn();
    } else {
      this.syncAll();
      this.setInputEnabled(false);
      await wait(this, 300);
      this.showResult();
    }
  }

  /** `stack` lifts a status label above the ones already showing on that target in the same beat (#64). */
  private async playEvent(e: CombatEvent, stack = 0): Promise<void> {
    const who = (e as { who?: number }).who ?? 0;
    const view = this.views[who] ?? this.views[0]!;
    const sprite = (side: 'player' | 'enemy') => (side === 'player' ? this.playerSprite : view.sprite);
    const pos = (side: 'player' | 'enemy') => (side === 'player' ? { x: this.px, y: this.py } : { x: view.x, y: view.y });
    switch (e.t) {
      case 'roundStart': {
        this.cast = null;
        this.roundText.setText(`Round ${e.round}  ·  screen ${this.session.screenIndex + 1}`);
        this.phaseText.setText('YOUR TURN').setColor(COLORS.gold);
        // Belt and braces: every panel reflects this round's intent from the first frame of the round.
        for (const en of this.state.enemies) {
          if (en.dead) { this.hideIntent(en.slot); continue; }
          const ci = currentIntent(this.state, en.slot);
          this.showIntent(ci.intent, en.next.posture, ci.predictedDamage, ci.moveName, en.slot);
        }
        this.setTarget(this.target, true);
        // The hardened/warded/exposed countdowns ticked at end of round; show the ticked values now.
        this.snapStatuses(); this.syncChips();
        await wait(this, 250);
        return;
      }
      case 'deal': {
        this.displayHand = e.hand.slice();
        this.rebuildHand();
        const card = this.hand[this.hand.length - 1];
        if (card) { card.setScale(0.2); await tween(this, { targets: card, scale: 1, duration: 180, ease: 'Back.Out' }); }
        this.pileText.setText(`deck ${this.state.player.deck.length}  ·  hand ${this.state.player.hand.length}  ·  discard ${this.state.player.discard.length}`);
        return;
      }
      case 'exhaust': {
        await floatText(this, this.px, this.py - 110, 'spent for this fight', COLORS.muted, 20, 900);
        return;
      }
      case 'consumed': {
        await floatText(this, this.px, this.py - 110, 'tome spent', '#ffd166', 24, 1000);
        return;
      }
      case 'hold': {
        const card = this.hand.find((c) => c.skillId === e.skill);
        if (card) { for (const c of this.hand) c.setEnabled(false); await tween(this, { targets: card, y: card.y + 70, alpha: 0, duration: 180, ease: 'Quad.In' }); }
        this.dropFromDisplay(e.skill);
        this.rebuildHand();
        await floatText(this, this.px, this.py - 70, 'held back', COLORS.muted, 26, 900);
        return;
      }
      case 'counter': {
        this.cameras.main.shake(120, 0.007);
        if (e.blocked) { this.dispGuardHit('player'); this.syncChips(); }
        else this.showHp('player', -e.amount);
        await floatText(this, this.px, this.py - 30, e.blocked ? 'COUNTER BLOCKED' : `COUNTERED  -${e.amount}`, '#ff9f68', 34);
        return;
      }
      case 'handOverflow': {
        const card = this.hand.find((c) => c.skillId === e.discarded);
        if (card) await tween(this, { targets: card, y: card.y + 60, alpha: 0, duration: 200, ease: 'Quad.In' });
        this.dropFromDisplay(e.discarded);
        this.rebuildHand();
        await this.toast(`${skillInCombat(this.state, e.discarded).name} slipped from your hand`);
        return;
      }
      case 'reshuffle':
        await this.toast('deck reshuffled');
        return;
      case 'redraw': {
        // Every card goes back in: the hand empties, and the deals that follow fill it again.
        for (const c of this.hand) this.tweens.add({ targets: c, y: c.y + 70, alpha: 0, duration: 160, ease: 'Quad.In' });
        await wait(this, 180);
        this.displayHand = [];
        this.rebuildHand();
        await this.toast('Earthen Relic: every card shuffled, a fresh hand');
        return;
      }
      case 'pierce': {
        const p = pos('enemy');
        await floatText(this, p.x, p.y - 60, 'PIERCE', '#e0c080', 26, 700);
        return;
      }
      case 'intent':
        this.showIntent(e.intent, e.posture, e.predictedDamage, e.moveName, who);
        return;
      case 'play': {
        const s = sprite(e.side), p = pos(e.side);
        const dir = e.side === 'player' ? 1 : -1;
        if (e.side === 'enemy') {
          // A clear beat between your action and the enemy's, naming the move it promised.
          this.phaseText.setText(`ENEMY TURN · ${view.def.name}: ${e.name}`).setColor('#ffb4b4');
          view.intentBg.setStrokeStyle(3, 0xff6b6b);
          await wait(this, 450);
        }
        if (e.side === 'player') {
          // The played card leaves the hand first, visibly, so "used" is never in doubt.
          const card = this.hand.find((c) => c.skillId === e.skill);
          if (card) {
            for (const c of this.hand) c.setEnabled(false);
            await tween(this, { targets: card, y: card.y - 70, alpha: 0, scale: 0.85, duration: 160, ease: 'Quad.In' });
          }
          this.dropFromDisplay(e.skill);
          this.rebuildHand();
        }
        // The name hangs over the actor while the lunge happens, instead of one after the other.
        void floatText(this, p.x, p.y - 84, e.name, e.side === 'player' ? COLORS.gold : '#ffb4b4', 24, 1300);
        await wait(this, 200);
        await tween(this, { targets: s, x: p.x + 28 * dir, duration: 110, yoyo: true, ease: 'Quad.Out' });
        this.cast = { kind: e.vfx ?? 'none', side: e.side, who, done: new Set() };
        if (e.vfx === 'heal') this.fx.heal(p);
        if (e.vfx === 'sandwich') void this.fx.sandwich(p);
        if (e.vfx === 'cards') void this.fx.cards(p);
        return;
      }
      case 'damage': {
        const s = sprite(e.target), p = pos(e.target), fromRight = e.target === 'player';
        const kind = this.cast?.kind ?? 'slash';
        // A block shows the shield that stopped it (#62, #63): Guard white, Ward yellow, Aegis gold. The
        // slash or spell stops at that shield instead of reaching the body (#66).
        const guard = e.blocked ? { target: s, color: blockColor(e.kind, this.statusList(e.target, e.target === 'enemy' ? who : undefined).some((x) => x.id === 'aegis')), fromRight } : undefined;
        const shielded = await this.castAt(e.target, who, p, guard);
        if (guard && !shielded) {
          if (kind === 'slash') void this.fx.slashBlocked(s, e.amount, guard.color, fromRight);
          else this.fx.deflect(s, guard.color, blockSide(kind, fromRight));
        } else if (!e.blocked && kind === 'slash') void this.fx.slash(p, e.amount, fromRight);
        else if (!e.blocked && e.hit > 1) this.fx.burst(p, 0xffffff, 5, 40, 300, 0.25);
        if (e.blocked) {
          this.dispGuardHit(e.target, e.kind === 'magic' ? 'ward' : 'guard', who);
          this.syncChips();
          await floatText(this, p.x, p.y - 30, 'BLOCKED', COLORS.block, 30, 900);
        } else {
          this.cameras.main.shake(90, 0.005);
          void tween(this, { targets: s, x: p.x + (e.target === 'player' ? -10 : 10), duration: 50, yoyo: true, repeat: 1 });
          this.showHp(e.target, -e.amount, who);
          // Multi-hit numbers stagger sideways so they do not stack on top of each other.
          const dx = e.hits > 1 ? (e.hit - (e.hits + 1) / 2) * 34 : 0;
          const p2 = e.crit
            ? floatText(this, p.x + dx, p.y - 34, `-${e.amount}!`, '#ffb02e', 54, 1200)
            : floatText(this, p.x + dx, p.y - 30, `-${e.amount}`, COLORS.damage, 40, 1100);
          await (e.hits > 1 && e.hit < e.hits ? wait(this, 260) : p2);
        }
        return;
      }
      case 'heal': {
        const p = pos(e.side);
        this.showHp(e.side, e.amount, who);
        await floatText(this, p.x, p.y - 30, `+${e.amount}`, COLORS.heal, 36);
        return;
      }
      case 'burn': {
        const p = pos(e.side);
        this.phaseText.setText('END OF ROUND').setColor(COLORS.muted);
        this.showHp(e.side, -e.amount, who);
        await floatText(this, p.x, p.y - 30, `${e.status === 'curse' ? 'curse' : 'burn'} -${e.amount}`, e.status === 'curse' ? '#c084fc' : COLORS.burn, 28);
        return;
      }
      case 'statusApplied': {
        // A curse, burn, chill or hex cast without a hit still shows its spell (the rain cloud for Static Field).
        if (this.cast && this.cast.side !== e.side) await this.castAt(e.side, who, pos(e.side));
        // Every status flashes its own coloured shield on whoever gained it (#59, #62).
        this.fx.glow(sprite(e.side), SHIELD_COLOR[e.status]);
        this.dispUpsert(e.side, { id: e.status, turns: e.turns, magnitude: e.magnitude }, who);
        this.syncChips();
        // Guard is self-evident from the chip and the card name; everything else gets a callout.
        // Lunch Break and Blackjack are named by the card that gave them (#69): no second callout over the name.
        if (e.status === 'guard' || (e.side === 'player' && (e.status === 'regen' || e.status === 'blackjack'))) { await wait(this, 350); return; }
        const p = pos(e.side);
        const m = STATUS_LABELS[e.status];
        // On an enemy a stun is a stun (Bellow, DECISIONS #88); "Recovering" is the player's word.
        await floatText(this, p.x, p.y - 110 - stack * 28, e.side === 'enemy' && e.status === 'stun' ? 'STUNNED' : m.label, m.color, 22, 900);
        return;
      }
      case 'statusExpired':
        this.dispRemove(e.side, e.status, who);
        this.syncChips();
        // A removal (DECISIONS #48) is the card's doing, so it gets a callout; a status running out does not.
        if (e.stripped) { const p = pos(e.side); await floatText(this, p.x, p.y - 110, `${STATUS_LABELS[e.status].label} removed`, COLORS.muted, 22, 700); }
        return;
      case 'statusResisted': {
        const p = pos(e.side);
        // The spell is still seen being cast before the Ward stops it (#62).
        const guard = e.warded ? { target: sprite(e.side), color: SHIELD_COLOR.ward, fromRight: e.side === 'player' } : undefined;
        const shielded = this.cast && this.cast.side !== e.side ? await this.castAt(e.side, who, p, guard) : false;
        if (guard && !shielded) this.fx.deflect(guard.target, guard.color, blockSide(this.cast?.kind ?? 'none', guard.fromRight));
        if (e.warded) { this.dispGuardHit(e.side, 'ward', who); this.syncChips(); await floatText(this, p.x, p.y - 30, 'WARDED', COLORS.block, 30, 900); return; }
        if (e.immune) { await floatText(this, p.x, p.y - 30, `IMMUNE: ${e.status.toUpperCase()}`, '#c9b27a', 24, 900); return; }
        await floatText(this, p.x, p.y - 30, 'resisted', '#c7b3ff', 26, 900);
        return;
      }
      case 'chilled': {
        const p = pos(e.side);
        this.phaseText.setText('ENEMY TURN').setColor('#ffb4b4');
        await floatText(this, p.x, p.y - 30, 'CHILLED · skips', '#9ad7ff', 30);
        return;
      }
      case 'stunned': {
        const p = pos(e.side);
        await floatText(this, p.x, p.y - 30, e.side === 'enemy' ? 'stunned · turn skipped' : 'recovering · turn skipped', '#ffd166', 26);
        return;
      }
      case 'phase':
        this.bark(who, 'rage');
        await this.bannerShow(`${view.def.name} rages!`);
        return;
      case 'crit':
        // Luck (DECISIONS #50): the card's hits land at +50%; the numbers that follow are gold and big.
        this.cameras.main.shake(160, 0.01);
        await this.luckFanfare('CRITICAL HIT!', '#ffb02e', 'every hit +50%');
        return;
      case 'backfire': {
        // The card did not kill (DECISIONS #51): it turns on you, unblockable.
        this.cameras.main.shake(220, 0.012);
        this.cameras.main.flash(180, 160, 40, 200);
        this.showHp('player', -e.amount);
        void floatText(this, this.px, this.py - 30, `-${e.amount}`, '#d06bff', 52, 1300);
        await this.luckFanfare('BACKFIRE!', '#d06bff', 'it survived, and the spell turns on you');
        return;
      }
      case 'bonusTurn':
        this.cameras.main.flash(220, 120, 255, 180);
        await this.luckFanfare('BONUS TURN!', '#7cffb2', 'play again before they move');
        this.phaseText.setText('YOUR TURN · BONUS').setColor('#7cffb2');
        return;
      case 'coin': {
        // Trickster (#69): the coin flips over the hero and lands on what came up.
        await this.fx.coin({ x: this.px, y: this.py - 90 }, e.result);
        await floatText(this, this.px, this.py - 60, `${e.result.toUpperCase()}! ${e.won ? 'you called it' : 'wrong call'}`, e.won ? '#ffd166' : '#ff6b6b', 26, 1000);
        return;
      }
      case 'thorns': {
        // A cursed enemy's thorns (#73): it hurts to hit.
        this.showHp('player', -e.amount);
        this.cameras.main.shake(70, 0.004);
        await floatText(this, this.px, this.py - 40, `thorns -${e.amount}`, '#ff6b6b', 26, 800);
        return;
      }
      case 'blackjack':
        void floatText(this, this.px, this.py - 120, `${e.total} / 21`, e.total >= 17 ? '#ff6b6b' : '#ffd700', 30, 1300);
        return;
      case 'blackjackDraw':
        // The opening card (#71): it flips in over the hero, then the total it starts.
        await wait(this, 450);
        await this.fx.playingCard({ x: this.px, y: this.py - 110 }, e.rank, e.suit);
        void floatText(this, this.px + 70, this.py - 110, `${e.total} / 21`, e.total >= 17 ? '#ff6b6b' : '#ffd700', 30, 1300);
        await wait(this, 500);
        return;
      case 'blackjackHand': {
        // The hand was played at the table (DECISIONS #88): here the verdict.
        await this.luckFanfare(e.won ? 'BLACKJACK WIN' : e.total > 21 ? 'BUST' : 'DEALER WINS', e.won ? '#ffd700' : '#ff6b6b', e.won ? `${e.total} beats 16: double damage` : `${e.total} vs 16: nothing lands, you are Exposed`);
        return;
      }
      case 'bust':
        this.cameras.main.shake(260, 0.014);
        this.showHp('player', -this.state.player.stats.maxHp);
        await this.luckFanfare('BUST!', '#ff3355', `${e.total} is over 21`);
        return;
      case 'plays': {
        // One card per enemy alive when the turn began (DECISIONS #68); a bonus turn adds one.
        const bonus = !!this.state.bonusTaken;
        this.phaseText.setText(`YOUR TURN · ${e.left === 1 ? '1 MORE CARD' : `${e.left} CARDS`}${bonus ? ' · BONUS' : ''}`).setColor(bonus ? '#7cffb2' : COLORS.gold);
        if (!this.state.log.some((x, i) => x.t === 'plays' && i < this.state.log.indexOf(e))) {
          // The first time in a fight, say why.
          const n = this.state.enemies.filter((x) => !x.dead).length;
          await floatText(this, this.scale.gameSize.width / 2, this.handY - 120, `${n} enemies: ${e.left} cards before they move`, COLORS.gold, 26, 1300);
        }
        return;
      }
      case 'death': {
        const s = sprite(e.side);
        if (s instanceof Phaser.GameObjects.Sprite) s.anims.stop();
        this.tweens.killTweensOf(s); // the breathing stops with the body
        if (e.side === 'enemy') { this.bark(who, 'death'); s.disableInteractive(); this.hideIntent(who); view.slain = true; view.hp.setDead(); view.chips.set([]); view.stats.setVisible(false); view.nameText.setAlpha(0.4); }
        await tween(this, { targets: s, alpha: 0.15, y: s.y + 10, duration: 350 });
        if (e.side === 'enemy' && this.target === who) this.setTarget(-1, true);
        return;
      }
      case 'end':
        return;
    }
  }

  /**
   * Play the current move's spell at this target once (#59); a slash or no effect has no travel. With a
   * `guard` the spell stops at the shield (#66); true when the spell raised that shield itself.
   */
  private async castAt(target: 'player' | 'enemy', who: number, to: { x: number; y: number }, guard?: Guard): Promise<boolean> {
    const c = this.cast;
    if (!c || c.side === target || c.kind === 'slash' || c.kind === 'none' || SELF_VFX.includes(c.kind)) return false;
    const key = `${target}:${target === 'enemy' ? who : 0}`;
    if (c.done.has(key)) return false;
    c.done.add(key);
    const from = c.side === 'player' ? { x: this.px + 20, y: this.py - 30 } : { x: this.views[c.who]?.x ?? to.x, y: (this.views[c.who]?.y ?? to.y) - 10 };
    // Just above the target's head, for a cloud or a skull (#62).
    const s = (target === 'player' ? this.playerSprite : this.views[who]?.sprite ?? this.playerSprite) as unknown as { x: number; y: number; displayHeight: number; originY?: number };
    const head = { x: s.x, y: s.y - (s.originY === 1 ? s.displayHeight : s.displayHeight / 2) - 6 };
    return this.fx.cast(c.kind, from, { x: to.x, y: to.y - 10 }, head, guard);
  }

  private async toast(msg: string) {
    const t = this.add.text(this.scale.gameSize.width / 2, this.handY - 70, msg, { ...text.small, fontSize: '14px', color: COLORS.text }).setOrigin(0.5).setAlpha(0);
    await tween(this, { targets: t, alpha: 1, duration: 120 });
    await wait(this, 500);
    await tween(this, { targets: t, alpha: 0, duration: 200 });
    t.destroy();
  }

  /** Luck's moments (DECISIONS #50): a big coloured callout with a line under it and a burst of sparks. */
  private async luckFanfare(msg: string, color: string, sub: string) {
    const { width: W, height: H } = this.scale.gameSize;
    const big = this.add.text(W / 2, H * 0.3, msg, { ...text.title, fontSize: '44px', color, stroke: '#000000', strokeThickness: 8 }).setOrigin(0.5).setDepth(65).setScale(0.3).setAlpha(0);
    const line = this.add.text(W / 2, H * 0.3 + 36, sub, { ...text.body, fontSize: '15px', color: '#ffffff', fontStyle: 'bold', stroke: '#000000', strokeThickness: 4 }).setOrigin(0.5).setDepth(65).setAlpha(0);
    for (let i = 0; i < 12; i++) {
      const spark = this.add.text(W / 2 + (Math.random() - 0.5) * 80, H * 0.3, '✦', { fontFamily: FONT, fontSize: `${14 + Math.random() * 12}px`, color: i % 2 ? color : '#ffffff' }).setOrigin(0.5).setDepth(64);
      this.tweens.add({ targets: spark, x: spark.x + (Math.random() - 0.5) * 360, y: spark.y + (Math.random() - 0.6) * 180, alpha: 0, angle: 180, duration: 800 + Math.random() * 400, ease: 'Quad.Out', onComplete: () => spark.destroy() });
    }
    void tween(this, { targets: line, alpha: 1, duration: 200, delay: 120 });
    await tween(this, { targets: big, scale: 1, alpha: 1, duration: 260, ease: 'Back.Out' });
    await wait(this, 650);
    await tween(this, { targets: [big, line], alpha: 0, duration: 200 });
    big.destroy(); line.destroy();
  }

  private async bannerShow(msg: string) {
    this.banner.setText(msg).setAlpha(0).setScale(0.8);
    await tween(this, { targets: this.banner, alpha: 1, scale: 1, duration: 200, ease: 'Back.Out' });
    await wait(this, 700);
    await tween(this, { targets: this.banner, alpha: 0, duration: 200 });
  }

  // ---------------------------------------------------------------- result

  private showResult() {
    const { width: W, height: H } = this.scale.gameSize;
    const won = this.state.outcome === 'won';
    const isBoss = this.encounter.kind === 'boss';
    this.add.rectangle(W / 2, H / 2, W, H, 0x000000, 0.6).setDepth(70);
    const names = this.state.enemyDefs.map((d) => d.name).join(' & ');
    const title = won ? (isBoss ? `${names} fall${this.state.enemyDefs.length === 1 ? 's' : ''}!` : 'Victory') : 'You died';
    this.add.text(W / 2, H * 0.34, title, { ...text.title, color: won ? COLORS.gold : '#ff6b6b' }).setOrigin(0.5).setDepth(71);
    recordFight(this, this.session, this.encounter, this.hpBefore, this.state.player.hp, this.state.log, won ? 'won' : 'lost');
    // What a growing card gained this fight stays with the run (Cursed Counter, DECISIONS #73).
    if (!this.session.testMode) this.session.skillGrowth = { ...this.state.growth };

    if (this.session.testMode) {
      // Sandbox: no spoils, no death, nothing saved. Straight back into the same fight or the setup.
      this.add.text(W / 2, H * 0.34 + 46, `${won ? 'Won' : 'Lost'} in ${this.state.round} rounds  ·  ${this.state.player.hp}/${this.session.stats.maxHp} HP left  ·  ${this.state.enemies.map((en) => `${this.state.enemyDefs[en.slot]!.name} ${en.hp}/${en.stats.maxHp}`).join(', ')}`, text.body).setOrigin(0.5).setDepth(71);
      new Button(this, W / 2 - 120, H * 0.62, 'Fight again', () => { this.session.hp = this.session.stats.maxHp; this.scene.start('Combat'); }, { width: 200, fill: 0x1f2a44, edge: COLORS.goldHex }).setDepth(72);
      new Button(this, W / 2 + 120, H * 0.62, 'Setup', () => this.scene.start('TestMode'), { width: 200 }).setDepth(72);
      return;
    }

    const spent = spendConsumedTomes(this.session, this.state.player.consumed);
    if (spent.length) void persistRun(this);
    if (won) {
      // EXP for the kill(s) goes to this class's progression (DECISIONS #32) and survives the run.
      // A cursed win pays three times the EXP and gold, and offers the cursed pool after the spoils (DECISIONS #73).
      const mult = this.encounter.cursed ? CURSED_REWARD_MULT : 1;
      const exp = mult * this.state.enemyDefs.reduce((a, d) => a + expForEnemy(d, this.encounter.kind, this.state.enemyDefs.length), 0);
      // Training (DECISIONS #96) pays no EXP: it is off the record, and a level-up there would only confuse.
      const gained = this.session.training ? { from: 0, to: 0, points: 0 } : gainExp(getMeta(this), this.session.classId, exp);
      void persistMeta(this);
      if (!this.session.training) this.add.text(W / 2, H * 0.34 + 74, `+${exp} EXP`, { ...text.body, fontSize: '15px', color: COLORS.gold, fontStyle: 'bold' }).setOrigin(0.5).setDepth(71);
      this.session.hp = this.state.player.hp;
      if (gained.to > gained.from) {
        // Each level: +1 max HP for good, and a rare card or gold (DECISIONS #49).
        const rewards = applyLevelUp(this.session, getMeta(this), gained.to - gained.from);
        void persistMeta(this); void persistRun(this);
        this.levelUpFanfare(gained.to, gained.points, rewards.map((r) => (r.kind === 'tome' ? getSkill(r.id).name : `${r.amount} gold`)));
      }
      this.session.encountersWon += 1;
      // The win changes the run now, before any save (DECISIONS #61); the map only shows it.
      const report = applyWin(this.session, getMeta(this), this.encounter);
      void persistMeta(this); void persistRun(this);
      this.session.lastResult = { encounter: this.encounter, won: true, report };
      this.session.pendingEncounter = null;
      let extra = spent.length ? `  Spent: ${spent.join(', ')}.` : '';
      if (this.encounter.ghost) {
        // Beating your ghost gives back what it died holding (DECISIONS #36).
        const g = ghostOn(getMeta(this), this.session.screenIndex);
        if (g) {
          const sp = ghostSpoils(g);
          this.session.gold += sp.gold;
          let learned = '';
          if (sp.tome && this.session.deck.length < 10) { applyTome(this.session, getSkill(sp.tome)); learned = ` and ${getSkill(sp.tome).name}`; }
          extra += `  The ghost is laid. You recover ${sp.gold} gold${learned}.`;
          layGhost(getMeta(this), this.session.screenIndex);
          void persistMeta(this);
        }
      }
      if (this.enemyDef.id === 'wren') { nudgeRelation(getMeta(this), 'wren', 9); this.session.flags.add('wren_beaten'); extra += '  Wren sits down by the giant. "Fine," she says. "Fine."'; void persistMeta(this); }
      if (this.encounter.cursed) extra += `  The curse lifts: ${CURSED_REWARD_MULT}× gold and EXP.`;
      const sub = (isBoss
        ? 'The way forward opens. You are fully healed.'
        : `${this.session.hp}/${this.session.stats.maxHp} HP. No healing between fights.`) + extra;
      this.add.text(W / 2, H * 0.34 + 46, sub, text.body).setOrigin(0.5).setDepth(71);
      const source = this.encounter.kind === 'random' || this.encounter.kind === 'node' ? (this.encounter.extra?.length ? 'guard' : 'kill') : this.encounter.kind; // a duo (or elite) pays like a guard
      this.session.pendingOffer = this.encounter.cursed ? { source, goldMult: CURSED_REWARD_MULT, then: { source: 'cursed' } } : { source, ...(isBoss ? { bossId: this.enemyDef.id } : {}) };
      new Button(this, W / 2, H * 0.62, 'Take spoils', () => this.scene.start('Reward'), { width: 220, fill: 0x1f2a44, edge: COLORS.goldHex }).setDepth(72);
    } else {
      this.session.lastResult = { encounter: this.encounter, won: false };
      recordDeath(getMeta(this), this.session.screenIndex, this.killerId());
      const killer = this.killerName();
      // Your death stays on the map as a ghost at the clearing you fell in (DECISIONS #36); a gate death leaves none.
      if (this.session.map.authored && this.encounter.kind !== 'boss') {
        leaveGhost(getMeta(this), { classId: this.session.classId, screenIndex: this.session.screenIndex, tile: { ...this.session.playerPos }, nodeId: this.encounter.nodeId, guardId: this.encounter.guardId, deck: [...this.session.deck], stats: { ...this.session.stats }, equipment: equipmentToIds(this.session.equipment), killer: this.killerId(), killerName: killer, gold: this.session.gold });
      }
      void Promise.all([persistMeta(this), endSavedRun(this)]);
      this.add.text(W / 2, H * 0.34 + 46, `Slain by ${killer} on screen ${this.session.screenIndex + 1}.`, text.body).setOrigin(0.5).setDepth(71);
      new Button(this, W / 2, H * 0.62, 'Continue', () => this.scene.start('RunEnd', { won: false, killedBy: killer }), { width: 220, fill: 0x1f2a44, edge: COLORS.goldHex }).setDepth(72);
    }
  }

  private quit() {
    if (this.session.testMode) { this.scene.start('TestMode'); return; }
    // Leaving mid-fight forfeits the fight but not the run: the map state was saved before the encounter.
    setSession(this, null);
    this.scene.start('Title');
  }
}
