export const SCREEN_COUNT = 2;

export type EncounterKind = 'random' | 'guard' | 'boss' | 'node';
/** `tile` is where the fight started; the combat backdrop is chosen from it (docs/ART.md). */
export interface PendingEncounter { /** A cursed enemy (DECISIONS #73): 3× gold and EXP and a cursed card offer if won. */ cursed?: boolean; kind: EncounterKind; enemyId: EnemyId; guardId?: string; /** Authored map node (kind 'node'). */ nodeId?: string; tile?: TileType; /** Further enemies behind the first (duos, DECISIONS #29). */ extra?: EnemyId[]; /** Full definitions when the fight holds enemies that are not in the roster (a ghost, a boss variant; DECISIONS #36). Front first; overrides enemyId/extra for the engine. */ custom?: Enemy[]; /** Set when your ghost is in this fight. */ ghost?: boolean; /** The enemy the map showed when this one is a surprise (DECISIONS #81). */ surprise?: EnemyId; }
export interface CombatResult { encounter: PendingEncounter; won: boolean; /** What the win already changed (applied in combat, DECISIONS #61); the map only shows it. */ report?: import('@game/story').WinReport; }
/** A reward to show. `goldMult` scales the rolled gold and `then` is the offer that follows (a cursed win, DECISIONS #73). */
export interface PendingOffer {
  source: RewardSource | 'cursed'; gold?: number; goldMult?: number; then?: PendingOffer;
  /** A boss's loot (DECISIONS #82): that boss's own items may be offered. */ bossId?: string;
  /** Exactly these items, no roll (the Treasure Dungeon's chest, DECISIONS #84). */ fixed?: string[];
  /** The screen's title instead of the source's. */ title?: string;
}

export interface RunSession {
  seed: string;
  rng: RunRng;
  classId: ClassId;
  /** Primary family (the first heirloom pick); kept for labels and telemetry. */
  setId: SetId;
  /** Families whose tomes drop this run: the heirloom picks' sets (DECISIONS #32). */
  families: SetId[];
  base: Stats;
  stats: Stats;
  hp: number;
  gold: number;
  deck: SkillId[];
  equipment: Equipment;

  screenIndex: number;
  map: ScreenMap;
  playerPos: Tile;
  threat: number;
  openedPois: Set<string>;
  usedShrines: Set<string>;
  defeatedGuards: Set<string>;
  /** Node overworld (DECISIONS #37): nodes whose task is done, and the last monster node cleared (quests re-arm it). */
  clearedNodes: Set<string>;
  lastClearedNode: string | null;
  /** In the Treasure Dungeon (DECISIONS #84): screen 1's state, put back on the way out. */
  surface?: SurfaceState;
  /** The Treasure Dungeon was entered and left this run: its door is sealed. */
  dungeonDone?: boolean;
  /** Run-scoped story flags set by dialogue options (DECISIONS #35). */
  flags: Set<string>;
  /** A special run (DECISIONS #58): rolled once at the start; each screen offers its special quest when one qualifies. */
  special: boolean;
  bossDefeated: boolean;
  encountersWon: number;
  newDiscoveries: string[];
  heirloomName: string | null;
  shop: ShopStock;
  quests: Quest[];
  skillUpgrades: SkillUpgrades;
  /** What each growing card has gained this run (Cursed Counter, DECISIONS #73). */
  skillGrowth: Record<SkillId, number>;
  /** Starting cards sold at a shop this run, one entry per copy (DECISIONS #81). */
  soldBasics: SkillId[];
  customItems: Item[];

  pendingEncounter: PendingEncounter | null;
  lastResult: CombatResult | null;
  pendingOffer: PendingOffer | null;
  /** Heirloom spread to pick from before the run starts; empty once chosen. */
  heirloomChoices: Heirloom[];
  /** Test Mode sandbox: never saved, logged or counted. */
  testMode?: boolean;
  /**
   * Level select (DECISIONS #76): a normal run started on a chosen screen, played against a copy of the
   * meta. Never saved, logged or counted; the real meta and the saved run are left as they were.
   */
  levelTest?: boolean;
  /** Demo mode (DECISIONS #93): only Doom cards, dealt instead of the starting cards. */
  demo?: boolean;
  /** The training run (DECISIONS #96): the lessons shown so far. Off the record like level select. */
  training?: { shown: string[] };
}

/** A run that leaves no trace: Test Mode or a level-select run. */
export const offRecord = (s: RunSession): boolean => !!(s.testMode || s.levelTest);

export type Store = SaveStore<MetaState, RunState>;

// ---------------------------------------------------------------- registry access

export const getSession = (scene: Phaser.Scene): RunSession => {
  const s = scene.registry.get('session') as RunSession | undefined;
  if (!s) throw new Error('No run session');
  return s;
};
export const peekSession = (scene: Phaser.Scene): RunSession | null => (scene.registry.get('session') as RunSession | undefined) ?? null;
export const setSession = (scene: Phaser.Scene, s: RunSession | null) => scene.registry.set('session', s);
export const getMeta = (scene: Phaser.Scene): MetaState => (scene.registry.get('meta') as MetaState | undefined) ?? createMeta();
export const setMeta = (scene: Phaser.Scene, m: MetaState) => scene.registry.set('meta', m);
export const getStore = (scene: Phaser.Scene): Store => scene.registry.get('store') as Store;

export async function persistRun(scene: Phaser.Scene): Promise<void> {
  const s = peekSession(scene);
  if (s && !offRecord(s)) await getStore(scene).saveRun(serialize(s));
}
export async function persistMeta(scene: Phaser.Scene): Promise<void> {
  if (peekSession(scene)?.levelTest) return; // a level-select run plays on a copy of the meta
  await getStore(scene).saveMeta(getMeta(scene));
}
/** Clear the saved run when a run ends; a level-select run never replaced it, so it stays. */
export async function endSavedRun(scene: Phaser.Scene): Promise<void> {
  if (peekSession(scene)?.levelTest) return;
  await getStore(scene).clearRun();
}

/**
 * Level select (DECISIONS #76): a fresh run of `classId` that starts on screen `screenIndex`, with the
 * usual heirloom pick. The caller swaps in a copy of the meta (holdMeta) so nothing the run does sticks.
 */
export function createLevelTest(classId: ClassId, meta: MetaState, screenIndex: number): RunSession {
  const s = createSession(classId, meta, `LEVEL${screenIndex + 1}-${Date.now()}`);
  s.levelTest = true;
  if (screenIndex !== 0) startScreen(s, screenIndex, meta);
  return s;
}
/**
 * Demo mode (DECISIONS #93): a level-select run whose whole hand is Doom, which kills every enemy.
 * No heirlooms and no starting cards; Doom locks out every other card (`locksCards`), so rewards, the
 * shop and level-ups add none. Off the record like any level-select run.
 */
export const DEMO_CARD = 'doom', DEMO_COPIES = 3;
export function createDemo(classId: ClassId, meta: MetaState, screenIndex: number): RunSession {
  const s = createLevelTest(classId, meta, screenIndex);
  s.demo = true;
  s.heirloomChoices = [];
  s.deck = Array<SkillId>(DEMO_COPIES).fill(DEMO_CARD);
  return s;
}
/**
 * The training run (DECISIONS #96): a warrior on the Training Grounds, off the record like a
 * level-select run, with no heirlooms and a little gold. Each stop's fight is set (TRAINING), and so
 * is its hand; the hero cannot die (`trainingCombat`).
 */
export function createTraining(meta: MetaState): RunSession {
  const s = createLevelTest('warrior', meta, 0);
  s.training = { shown: [] };
  s.heirloomChoices = [];
  s.gold = TRAINING_GOLD;
  const map = parseScreen(TRAINING1, s.rng.stream('training'), { seed: s.seed, screenIndex: 0, sub: { roster: enemiesOfTier(1).map((e) => e.id), pairs: PAIRS[1] } });
  delete map.dungeon;
  map.training = true;
  map.paint = 'map_training';
  map.bossId = '';
  roadOrder(map).forEach((n, i) => {
    const stop = TRAINING[i];
    if (!stop || stop.kind !== n.kind) throw new Error(`createTraining: stop ${i} is ${n.kind}, the script says ${stop?.kind}`);
    if (stop.enemies) { n.enemyId = stop.enemies[0]; if (stop.enemies.length > 1) n.extra = stop.enemies.slice(1); else delete n.extra; }
  });
  s.map = map;
  s.playerPos = { ...map.entry };
  s.clearedNodes = new Set();
  s.usedShrines = new Set();
  s.lastClearedNode = null;
  return s;
}
export const inTraining = (s: RunSession | null | undefined): boolean => !!s?.training;
/** The training stop at a node, if this is the training run. */
export const trainingStop = (s: RunSession, nodeId: string | undefined): TrainingStop | undefined => (s.training && nodeId ? TRAINING[stopIndex(s.map, nodeId)] : undefined);
/** The last training stop is cleared: training is over. */
export const trainingFinished = (s: RunSession): boolean => !!s.training && roadOrder(s.map).every((n, i) => TRAINING[i]!.kind !== 'monster' || s.clearedNodes.has(n.id));
/** What a training fight changes in createCombat: a set deal where the script gives one, and an HP floor of 1. */
export function trainingCombat(s: RunSession, nodeId: string | undefined): { basics?: SkillId[]; ordered?: boolean; floor?: number } {
  if (!s.training) return {};
  const stop = trainingStop(s, nodeId);
  return { floor: 1, ...(stop?.hand ? { basics: [...stop.hand], ordered: true } : {}) };
}

/** Swap a copy of the meta in for a level-select run; the title screen puts the real one back (restoreMeta). */
export function holdMeta(scene: Phaser.Scene): MetaState {
  const real = getMeta(scene);
  if (!scene.registry.get('metaHeld')) scene.registry.set('metaHeld', real);
  const copy = structuredClone(real);
  setMeta(scene, copy);
  return copy;
}
export function restoreMeta(scene: Phaser.Scene): void {
  const real = scene.registry.get('metaHeld') as MetaState | undefined;
  if (!real) return;
  setMeta(scene, real);
  scene.registry.remove('metaHeld');
}

// ---------------------------------------------------------------- creation & screens

export function rollSet(classId: ClassId, rng: RunRng): SetId {
  return rng.stream('meta').pick(getClass(classId).sets);
}

/** Class base plus permanent Legacy bonuses (DECISIONS #18). */
export function baseStatsFor(classId: ClassId, meta: MetaState): Stats {
  const c = getClass(classId).stats;
  // Each level past the first is LEVEL_HP max HP for good (DECISIONS #49).
  const levelHp = ((meta.progress[classId]?.level ?? 1) - 1) * LEVEL_HP;
  return { maxHp: c.maxHp + meta.legacy.maxHp + levelHp, atk: c.atk + meta.legacy.atk, def: c.def + meta.legacy.def, luck: c.luck ?? 0 };
}

export { LEVEL_GOLD };
export type LevelReward = { kind: 'tome'; id: SkillId } | { kind: 'gold'; amount: number };

/**
 * Levels gained mid-run (DECISIONS #49): each one adds its max HP to this run at once (and the
 * HP itself), then rolls a rare card from the run's families into the deck, or gold when the roll
 * misses, no rare card is left in the pool, or the deck is full.
 */
export function applyLevelUp(s: RunSession, meta: MetaState, levels: number, roll: () => number = () => s.rng.stream('level').next()): LevelReward[] {
  const out: LevelReward[] = [];
  for (let i = 0; i < levels; i++) {
    s.base.maxHp += LEVEL_HP;
    s.stats = computeStats(s.base, s.equipment);
    s.hp = Math.min(s.stats.maxHp, s.hp + LEVEL_HP);
    const rares = buildPool(poolCtx(s, meta)).tomes.filter((t) => t.rarity === 'rare');
    // Luck adds its 1.2% per point to the rare chance (DECISIONS #50).
    if (roll() < LEVEL_RARE_CHANCE + (s.stats.luck ?? 0) * LUCK_RARE_WEIGHT / 100 && rares.length && s.deck.length < DECK_CAP) {
      const pick = rares[Math.min(rares.length - 1, Math.floor(roll() * rares.length))]!;
      applyTome(s, pick);
      discoverSkill(meta, pick.id);
      out.push({ kind: 'tome', id: pick.id });
    } else {
      s.gold += LEVEL_GOLD;
      out.push({ kind: 'gold', amount: LEVEL_GOLD });
    }
  }
  return out;
}

export function createSession(classId: ClassId, meta: MetaState, seed = newSeed()): RunSession {
  const rng = new RunRng(seed);
  const setId = rollSet(classId, rng);
  const base = baseStatsFor(classId, meta);
  const s: RunSession = {
    seed, rng, classId, setId, families: unlockedSets(meta, classId), base: { ...base }, stats: { ...base }, hp: base.maxHp, gold: 0,
    deck: [], equipment: emptyEquipment(),
    screenIndex: 0, map: undefined as unknown as ScreenMap, playerPos: { x: 0, y: 0 }, threat: 0,
    openedPois: new Set(), usedShrines: new Set(), defeatedGuards: new Set(), clearedNodes: new Set(), lastClearedNode: null, flags: new Set(), special: STORY.enabled && rng.stream('special').chance(WORLD.specialChance ?? 0), bossDefeated: false, encountersWon: 0,
    newDiscoveries: [], heirloomName: null, shop: { lines: [], healPrice: 0, healPct: 0.5, healUsed: true }, quests: [], skillUpgrades: {}, skillGrowth: {}, soldBasics: [], customItems: [],
    pendingEncounter: null, lastResult: null, pendingOffer: null, heirloomChoices: [],
  };
  s.heirloomChoices = rollHeirloomChoices(meta, classId, rng.stream('meta'));
  startScreen(s, 0, meta);
  return s;
}

/**
 * Apply the heirloom picks (DECISIONS #32): tomes join the deck, and their families become the run's
 * tome pool. With no picks the pool stays every unlocked family.
 */
export function applyHeirlooms(s: RunSession, picks: Heirloom[], meta?: MetaState): void {
  const names: string[] = [];
  const fams: SetId[] = [];
  for (const h of picks) {
    if (h.kind === 'tome') {
      if (s.deck.length < DECK_CAP && s.deck.filter((d) => d === h.skill.id).length < TOME_COPY_CAP) s.deck.push(h.skill.id);
      names.push(h.skill.name);
      const fam = familyOf(s.classId, h.skill.id)?.id;
      if (fam && !fams.includes(fam)) fams.push(fam);
    } else { applyEquip(s, h.item); names.push(h.item.name); }
  }
  if (fams.length) { s.families = fams; s.setId = fams[0]!; }
  s.heirloomName = names.length ? names.join(' + ') : null;
  s.heirloomChoices = [];
  // The shop and quest were rolled before the picks; re-roll so they draw from the run's families.
  s.shop = rollShopStock(s.screenIndex, poolCtx(s, meta), s.rng.stream('loot'));
  setScreenQuest(s, meta ?? createMeta(), s.screenIndex, WORLD.quests.find((d) => d.id === currentQuest(s)?.defId) ?? null);
}

/**
 * A family bought on the skill tree during a run joins the run at once (its tomes drop from the
 * next reward on; the shop keeps its stock until the next screen). The heirloom rule "only the
 * picks' families drop" still holds for what the run started with.
 */
export function adoptFamily(s: RunSession, setId: SetId): boolean {
  if (s.families.includes(setId)) return false;
  s.families.push(setId);
  if (s.families.length === 1) s.setId = setId;
  return true;
}

/**
 * What every story condition reads, for dialogue and quests alike (DECISIONS #35, #61): run flags,
 * relations and deaths, level, class, gold, fights, the screen, each world.json quest's state, what
 * is held, whether the run is special, and what the world remembers across runs.
 */
export function storyCtx(s: RunSession, meta: MetaState): DialogueCtx {
  const quests: Record<string, QuestState> = {};
  for (const q of s.quests) if (q.defId && q.id.startsWith(`quest_${s.screenIndex}_`)) quests[q.defId] = q.status === 'active' && questReady(q, s.deck, s.equipment) ? 'ready' : q.status;
  return {
    flags: s.flags, relations: meta.relations ?? {}, deathsOnScreen: deathsOn(meta, s.screenIndex), deathsTotal: meta.deaths, lastKiller: meta.lastKiller,
    level: classProgress(meta, s.classId).level, classId: s.classId, gold: s.gold, fights: s.encountersWon, rng: s.rng.stream('quest'),
    screen: s.screenIndex, quests, has: (id) => s.deck.includes(id) || Object.values(s.equipment).some((i) => i?.id === id || i?.id?.startsWith(`${id}+`)),
    special: s.special, memory: new Set(meta.memory ?? []),
  };
}

/** Offer a world.json quest on this screen now (the dialogue `quest` effect, #61). False when it belongs to another screen. */
export function offerQuest(s: RunSession, meta: MetaState, id: string): Quest | null {
  const def = WORLD.quests.find((d) => d.id === id);
  if (!def || def.screen !== s.screenIndex) return null;
  const q = buildQuest(s, meta, def);
  q.id = `${q.id}_${s.quests.length}`;
  s.quests.push(q);
  return q;
}

/** The quest a screen offers this run (DECISIONS #57): its special one on a special run when one qualifies (#58), else a usual one. */
function pickScreenQuest(s: RunSession, meta: MetaState, index: number): QuestDef | null {
  if (!STORY.enabled) return null; // no quests while the story is switched off (#72)
  const ctx = storyCtx(s, meta);
  return (s.special ? pickQuestDef(WORLD.quests, index, ctx, true) : null) ?? pickQuestDef(WORLD.quests, index, ctx, false);
}
/** Put this screen's quest in place; earlier screens' quests stay for the run summary. */
function setScreenQuest(s: RunSession, meta: MetaState, index: number, def: QuestDef | null): void {
  const kept = s.quests.filter((q) => !q.id.startsWith(`quest_${index}_`));
  s.quests = def ? [...kept, buildQuest(s, meta, def)] : kept;
}
const buildQuest = (s: RunSession, meta: MetaState, def: QuestDef): Quest => questFromDef(def, s.map, { ...poolCtx(s, meta), screenIndex: s.screenIndex }, s.rng.stream('quest'));

/** Loot/quest context for this run: class, families, what is held. */
export const poolCtx = (s: RunSession, meta?: MetaState) => ({ classId: s.classId, families: s.families, meta: meta ?? createMeta(), deck: s.deck, equipment: s.equipment, luck: s.stats.luck ?? 0 });

/** Generate screen `index`, stock its shop, and put the player at its entry. */
export function startScreen(s: RunSession, index: number, meta?: MetaState): void {
  s.screenIndex = index;
  // The quest comes first: a special one pins nodes for this run (DECISIONS #58).
  const quest = pickScreenQuest(s, meta ?? createMeta(), index);
  s.map = parseScreen(index === 0 ? SCREEN1 : SCREEN2, s.rng.stream('map'), { seed: s.seed, screenIndex: index, rules: { ...nodeRules(index), ...(quest?.nodes ?? {}) } });
  s.playerPos = { ...s.map.entry };
  s.threat = 0;
  s.openedPois = new Set();
  s.usedShrines = new Set();
  s.defeatedGuards = new Set();
  s.clearedNodes = new Set();
  s.lastClearedNode = null;
  s.bossDefeated = false;
  s.shop = rollShopStock(index, poolCtx(s, meta), s.rng.stream('loot'));
  curseNodes(s, meta ?? createMeta());
  // About one fight in seven is not what the map shows (DECISIONS #81). After the curses, which it skips.
  rollSurprises(s.map.nodes ?? [], enemiesOfTier(screenTier(s)).map((e) => e.id), s.rng.stream('surprise'), { ...nodeRules(index), ...(quest?.nodes ?? {}) });
  // One quest per screen (DECISIONS #19), chosen from world.json (#57).
  setScreenQuest(s, meta ?? createMeta(), index, quest);
}

/** Where this screen's quest is offered and handed in: its giver node, else the start (Wren's camp). No quest, no giver (#72). */
export const questGiverNode = (s: RunSession): string | undefined => { const q = currentQuest(s); return q ? q.giverNode ?? s.map.nodes?.find((n) => n.kind === 'start')?.id : undefined; };

/** This screen's quest: the latest one, so the next link of a chain takes over once the last is handed in. */
export const currentQuest = (s: RunSession): Quest | undefined => s.quests.filter((q) => q.id.startsWith(`quest_${s.screenIndex}_`)).at(-1);
export const isEscorting = (s: RunSession): boolean => s.quests.some((q) => q.status === 'active' && q.escort?.following);

/**
 * Hand a quest in. Fetch: the carried copy is lost and a +1 version takes its
 * place (this run only). Hunt / escort: gold now and an offer the caller opens.
 */
export function turnInQuest(s: RunSession, q: Quest, meta?: MetaState): { gold: number; offer?: RewardSource; upgraded?: string } {
  if (!questReady(q, s.deck, s.equipment)) throw new Error('Quest not ready');
  q.status = 'done';
  s.gold += q.reward.gold;
  // The world editor's extras (DECISIONS #57): a flag, a relation, a card, and the next quest in a chain.
  if (q.reward.flag) s.flags.add(q.reward.flag);
  if (q.reward.relation && meta) nudgeRelation(meta, q.reward.relation.name, q.reward.relation.delta);
  if (q.reward.tome && s.deck.length < DECK_CAP) applyTome(s, getSkill(q.reward.tome));
  const next = q.then ? WORLD.quests.find((d) => d.id === q.then) : undefined;
  if (next) { const n = buildQuest(s, meta ?? createMeta(), next); n.id = `${n.id}_${s.quests.length}`; s.quests.push(n); }
  if (q.fetch) {
    if (q.fetch.type === 'tome') {
      s.skillUpgrades[q.fetch.id] = (s.skillUpgrades[q.fetch.id] ?? 0) + 1;
      return { gold: q.reward.gold, upgraded: upgradeSkill(getSkill(q.fetch.id), s.skillUpgrades[q.fetch.id]!).name };
    }
    const slot = (Object.keys(s.equipment) as (keyof Equipment)[]).find((k) => s.equipment[k]?.id === q.fetch!.id)!;
    const better = upgradeItem(s.equipment[slot]!);
    s.customItems.push(better);
    applyEquip(s, better);
    return { gold: q.reward.gold, upgraded: better.name };
  }
  return { gold: q.reward.gold, offer: q.reward.offer };
}

export const screenTier = (s: RunSession): 1 | 2 => (s.screenIndex === 0 ? 1 : 2);

// ---------------------------------------------------------------- node overworld (DECISIONS #37)

export const nodeById = (s: RunSession, id: string): MapNode => { const n = s.map.nodes?.find((x) => x.id === id); if (!n) throw new Error(`No node ${id}`); return n; };
export const nodeAt = (s: RunSession, t: Tile): MapNode | undefined => s.map.nodes?.find((n) => key(n.pos) === key(t));
/** The node the hero stands on (always one: travel ends on nodes). */
export const currentNode = (s: RunSession): MapNode => { const n = nodeAt(s, s.playerPos); if (!n) throw new Error('Hero is off the network'); return n; };
/** A node's task is done: entered and resolved (fight won, chest opened, chat had). Travel may pass through it. */
export const isCleared = (s: RunSession, n: MapNode): boolean => s.clearedNodes.has(n.id);

/**
 * The shrine (DECISIONS #81): visiting opens the road through it (cleared), healing spends it
 * (`usedShrines`). It heals SHRINE_HEAL of max HP, never past full.
 */
export const shrineUsed = (s: RunSession, n: MapNode): boolean => s.usedShrines.has(n.id);
export const shrineHeal = (s: RunSession): number => Math.max(0, Math.min(s.stats.maxHp - s.hp, Math.round(s.stats.maxHp * SHRINE_HEAL)));
export function useShrine(s: RunSession, n: MapNode): number {
  if (shrineUsed(s, n)) return 0;
  const heal = shrineHeal(s);
  s.hp += heal;
  s.usedShrines.add(n.id);
  s.clearedNodes.add(n.id);
  return heal;
}

/**
 * Nodes you can travel to now: anything linked through cleared nodes. The destination itself need
 * not be cleared (that is how you reach a fight), but nothing beyond an uncleared node is open.
 */
export function routeTo(s: RunSession, targetId: string): MapNode[] | null {
  const from = currentNode(s);
  const prev = new Map<string, string | null>([[from.id, null]]);
  const q = [from];
  for (let qi = 0; qi < q.length; qi++) {
    const n = q[qi]!;
    if (n.id === targetId) break;
    if (n.id !== from.id && !isCleared(s, n)) continue; // cannot pass through
    for (const l of n.links) if (!prev.has(l)) { prev.set(l, n.id); q.push(nodeById(s, l)); }
  }
  if (!prev.has(targetId)) return null;
  const out: MapNode[] = [];
  for (let id: string | null = targetId; id && id !== from.id; id = prev.get(id) ?? null) out.unshift(nodeById(s, id));
  return out;
}
export const reachableNodes = (s: RunSession): MapNode[] => (s.map.nodes ?? []).filter((n) => n.id !== currentNode(s).id && routeTo(s, n.id) !== null);

export const isFightNode = (n: MapNode): boolean => n.kind === 'monster' || n.kind === 'unknown' || n.kind === 'elite' || n.kind === 'boss';

/** The fight waiting at a node. */
export function nodeEncounter(s: RunSession, node: MapNode): PendingEncounter {
  // The Treasure Dungeon's five come 50% tougher (DECISIONS #84), duos and all.
  if (s.map.dungeon) {
    const ids = [node.enemyId!, ...(node.extra ?? [])];
    return { kind: 'node', enemyId: ids[0]!, nodeId: node.id, ...(ids.length > 1 ? { extra: ids.slice(1) } : {}), custom: ids.map((id) => dungeonEnemy(getEnemy(id))) };
  }
  if (node.kind === 'boss') return { kind: 'boss', enemyId: node.enemyId ?? s.map.bossId, nodeId: node.id };
  // A cursed node is one cursed enemy alone, even on a duo's node (DECISIONS #73).
  if (node.cursed) return { kind: 'node', enemyId: node.enemyId!, nodeId: node.id, cursed: true, custom: [cursedEnemy(getEnemy(node.enemyId!), node.cursed)] };
  // A surprise (DECISIONS #81): the map showed `enemyId`; this is who waits.
  if (node.surprise) return { kind: 'node', enemyId: node.surprise, nodeId: node.id, surprise: node.enemyId };
  return { kind: 'node', enemyId: node.enemyId!, nodeId: node.id, extra: node.extra ? [...node.extra] : undefined };
}

/** The player declined a cursed enemy (DECISIONS #73): the node holds its usual encounter from now on. */
export function liftCurse(_s: RunSession, node: MapNode): void { delete node.cursed; }

/**
 * Curse a few fight nodes (DECISIONS #73): each one a 5% chance, only for a class at level 3 or
 * higher. Its own stream, so the rest of the run rolls the same with or without curses.
 */
function curseNodes(s: RunSession, meta: MetaState): void {
  if (classProgress(meta, s.classId).level < CURSED_MIN_LEVEL) return;
  const rng = s.rng.stream('cursed');
  for (const n of s.map.nodes ?? []) {
    if ((n.kind !== 'monster' && n.kind !== 'unknown' && n.kind !== 'elite') || !n.enemyId) continue;
    if (rng.chance(CURSED_CHANCE)) n.cursed = rollCursedTraits(rng);
  }
}

/** A quest sends you back: the last cleared monster node gets a fresh fight, one head bigger than before, with its own words and win flag (#61). */
export function rearmLastFight(s: RunSession, rearm: Rearm = {}): MapNode | null {
  const id = s.lastClearedNode;
  if (!id) return null;
  const n = nodeById(s, id);
  if (!isFightNode(n) || n.kind === 'boss') return null;
  s.clearedNodes.delete(n.id);
  n.seen = true;
  delete n.surprise; // the re-armed fight is the one the map shows
  if (!n.extra?.length) {
    const pair = PAIRS[screenTier(s)].find(([front]) => front === n.enemyId) ?? s.rng.stream('encounter').pick(PAIRS[screenTier(s)]);
    n.enemyId = pair[0]; n.extra = [pair[1]];
  }
  s.flags.add('rearmed');
  n.rearm = { ...rearm };
  return n;
}

/** Treasure at a node, scaled by how far it sits from the start along the network. */
export function treasureGold(s: RunSession, node: MapNode): number {
  const hops = routeTo(s, node.id)?.length ?? 2;
  return 10 + (4 + Math.min(hops, 6) * 2) * (s.screenIndex + 1) + s.rng.stream('loot').int(0, 6);
}

// ---------------------------------------------------------------- taking rewards

export function applyEquip(s: RunSession, item: Item): Item | null {
  const r = equipItem(s.base, s.equipment, s.hp, item);
  s.equipment = r.equipment; s.hp = r.hp; s.stats = computeStats(s.base, s.equipment);
  return r.replaced;
}

/** True while the deck holds a card that locks out every other card (Cursed Counter, DECISIONS #73). */
export const cardsLocked = (s: RunSession): boolean => locked({ deck: s.deck });

/** Add a tome; at the deck cap the caller must pass the card to replace. Nothing is added while a lock is held (#73). */
export function applyTome(s: RunSession, skill: Skill, replaceId?: SkillId): void {
  if (cardsLocked(s)) return;
  if (s.deck.length >= DECK_CAP) {
    if (!replaceId) throw new Error('Deck full: a replacement is required');
    const i = s.deck.indexOf(replaceId);
    if (i < 0) throw new Error(`Not in deck: ${replaceId}`);
    s.deck[i] = skill.id;
  } else {
    s.deck.push(skill.id);
  }
}

/** Take a reward choice, record the discovery, and report whether it was new. */
export function takeChoice(s: RunSession, meta: MetaState, choice: RewardChoice, replaceSkillId?: SkillId): { isNew: boolean; replaced: Item | Skill | null } {
  if (choice.kind === 'tome') {
    const replaced = replaceSkillId ? getSkill(replaceSkillId) : null;
    applyTome(s, choice.skill, replaceSkillId);
    const isNew = discoverSkill(meta, choice.skill.id);
    if (isNew) s.newDiscoveries.push(choice.skill.id);
    return { isNew, replaced };
  }
  const replaced = applyEquip(s, choice.item);
  const isNew = discoverItem(meta, choice.item.id);
  if (isNew) s.newDiscoveries.push(choice.item.id);
  return { isNew, replaced };
}

/** The run's families for display; a run with none (a level-1 warrior, DECISIONS #41) is on basics and general tomes. */
export const setName = (s: RunSession) => (s.families.length ? s.families.map((id) => getSet(id).name).join(' + ') : 'basics only');

/** After a fight: fleeting tomes that were played leave the deck for good. Returns their names. */
export function spendConsumedTomes(s: RunSession, consumed: SkillId[]): string[] {
  const names: string[] = [];
  for (const id of consumed) {
    const i = s.deck.indexOf(id);
    if (i >= 0) { s.deck.splice(i, 1); names.push(getSkill(id).name); }
  }
  return names;
}

// ---------------------------------------------------------------- (de)serialisation

export function serialize(s: RunSession): RunState {
  return {
    version: RUN_VERSION, updatedAt: Date.now(),
    seed: s.seed, rngStates: s.rng.snapshot(), classId: s.classId, setId: s.setId, families: [...s.families], base: { ...s.base },
    hp: s.hp, gold: s.gold, deck: [...s.deck], equipment: equipmentToIds(s.equipment),
    screenIndex: s.screenIndex, map: s.map, playerPos: { ...s.playerPos }, threat: s.threat,
    openedPois: [...s.openedPois], usedShrines: [...s.usedShrines], defeatedGuards: [...s.defeatedGuards],
    clearedNodes: [...s.clearedNodes], lastClearedNode: s.lastClearedNode, flags: [...s.flags], special: s.special,
    ...(s.surface ? { surface: JSON.parse(JSON.stringify(s.surface)) as SurfaceState } : {}), ...(s.dungeonDone ? { dungeonDone: true } : {}),
    bossDefeated: s.bossDefeated, encountersWon: s.encountersWon, newDiscoveries: [...s.newDiscoveries], heirloomName: s.heirloomName,
    shop: JSON.parse(JSON.stringify(s.shop)) as ShopStock,
    quests: JSON.parse(JSON.stringify(s.quests)) as Quest[], skillUpgrades: { ...s.skillUpgrades }, skillGrowth: { ...s.skillGrowth }, soldBasics: [...s.soldBasics], customItems: JSON.parse(JSON.stringify(s.customItems)) as Item[],
  };
}

export function deserialize(st: RunState, meta: MetaState): RunSession {
  const rng = new RunRng(st.seed);
  rng.restore(st.rngStates);
  const base = st.base ?? baseStatsFor(st.classId, meta);
  const equipment = equipmentFromIds(st.equipment, st.customItems ?? []);
  return {
    seed: st.seed, rng, classId: st.classId, setId: st.setId, families: st.families ?? [st.setId], base, stats: computeStats(base, equipment),
    hp: st.hp, gold: st.gold, deck: [...st.deck], equipment,
    screenIndex: st.screenIndex, map: st.map, playerPos: { ...st.playerPos }, threat: st.threat,
    openedPois: new Set(st.openedPois), usedShrines: new Set(st.usedShrines), defeatedGuards: new Set(st.defeatedGuards),
    clearedNodes: new Set(st.clearedNodes ?? []), lastClearedNode: st.lastClearedNode ?? null, flags: new Set(st.flags ?? []), special: st.special ?? false,
    ...(st.surface ? { surface: st.surface } : {}), ...(st.dungeonDone ? { dungeonDone: true } : {}),
    bossDefeated: st.bossDefeated, encountersWon: st.encountersWon, newDiscoveries: [...st.newDiscoveries], heirloomName: st.heirloomName,
    shop: st.shop, quests: st.quests ?? [], skillUpgrades: st.skillUpgrades ?? {}, skillGrowth: st.skillGrowth ?? {}, soldBasics: (st.soldBasics ?? []) as SkillId[], customItems: st.customItems ?? [],
    pendingEncounter: null, lastResult: null, pendingOffer: null, heirloomChoices: [],
  };
}

// ---------------------------------------------------------------- selling a card (DECISIONS #81)

/** The starting cards this run deals every fight: the class's, less any sold at a shop. */
export function runBasics(s: RunSession): SkillId[] {
  if (s.demo) return []; // a demo hand is Doom alone (#93)
  const out = [...basicsFor(s.classId)];
  for (const id of s.soldBasics) { const i = out.indexOf(id); if (i >= 0) out.splice(i, 1); }
  return out;
}
/** A fight deals three cards at a time, so a run keeps at least this many. */
export const MIN_CARDS = 3;
export interface SellableCard { id: SkillId; from: 'deck' | 'basic'; value: number }
/** What a shop will buy: any card held, once per shop, while more than MIN_CARDS are held. */
export function sellableCards(s: RunSession): SellableCard[] {
  const basics = runBasics(s);
  if (s.shop.cardSold || s.deck.length + basics.length <= MIN_CARDS) return [];
  const value = (id: SkillId) => sellValue(getSkill(id).rarity, s.screenIndex);
  return [...s.deck.map((id) => ({ id, from: 'deck' as const, value: value(id) })), ...basics.map((id) => ({ id, from: 'basic' as const, value: value(id) }))];
}
/** Sell one copy of a card to this screen's shop: gold now, the card gone for the run. */
export function sellCard(s: RunSession, id: SkillId, from: 'deck' | 'basic'): number {
  const card = sellableCards(s).find((c) => c.id === id && c.from === from);
  if (!card) throw new Error(`sellCard: ${id} (${from}) cannot be sold here`);
  if (from === 'deck') s.deck.splice(s.deck.indexOf(id), 1);
  else s.soldBasics.push(id);
  s.gold += card.value;
  s.shop.cardSold = true;
  return card.value;
}

// ---------------------------------------------------------------- the Treasure Dungeon (DECISIONS #84)

/** The three things the chest may hold, one at random per run. */
export const DUNGEON_PRIZES = ['doomsday_armor', 'doomsday_device', 'the_goat'] as const;
export const inDungeon = (s: RunSession): boolean => !!s.map.dungeon;

/**
 * Go down: screen 1's map and where you stand are put aside, the dungeon is built (its fights from
 * the dungeon's five, its chest's prize rolled now), and you stand at its entrance.
 */
export function enterDungeon(s: RunSession, door: MapNode): void {
  if (s.dungeonDone || s.map.dungeon) throw new Error('enterDungeon: the door is sealed');
  s.clearedNodes.add(door.id);
  s.surface = { map: s.map, playerPos: { ...s.playerPos }, clearedNodes: [...s.clearedNodes], usedShrines: [...s.usedShrines], lastClearedNode: s.lastClearedNode, doorNode: door.id };
  const rng = s.rng.stream('dungeon');
  const map = parseScreen(DUNGEON1, rng, { seed: s.seed, screenIndex: s.screenIndex, sub: { roster: DUNGEON_ROSTER, pairs: DUNGEON_PAIRS } });
  map.paint = 'map_dungeon1';
  const chest = map.nodes!.find((n) => n.kind === 'treasure')!;
  chest.prize = rng.pick(DUNGEON_PRIZES);
  s.map = map;
  s.playerPos = { ...map.entry };
  const entrance = map.nodes!.find((n) => n.kind === 'start')!;
  s.clearedNodes = new Set([entrance.id]);
  s.usedShrines = new Set();
  s.lastClearedNode = null;
}

/** Come back up: screen 1 as it was, standing at the door, which is sealed for the rest of the run. */
export function leaveDungeon(s: RunSession): void {
  const up = s.surface;
  if (!up || !s.map.dungeon) throw new Error('leaveDungeon: not in the dungeon');
  s.map = up.map;
  const door = up.map.nodes!.find((n) => n.id === up.doorNode)!;
  s.playerPos = { ...door.pos };
  s.clearedNodes = new Set([...up.clearedNodes, door.id]);
  s.usedShrines = new Set(up.usedShrines);
  s.lastClearedNode = up.lastClearedNode;
  delete s.surface;
  s.dungeonDone = true;
}
