// Content types. Everything the game knows about classes, skills, items and
// enemies is data of these shapes. See docs/ARCHITECTURE.md §3.

export type ClassId = 'warrior' | 'wizard' | 'shaman';
export type SetId = string;
export type SkillId = string;
export type EnemyId = string;
export type Rarity = 'basic' | 'common' | 'uncommon' | 'rare' | 'boss';

export interface Stats {
  maxHp: number;
  atk: number;
  def: number;
  /** The part of `atk` that comes from gear. Added flat to every hit, never multiplied by a card (DECISIONS #31). */
  gearAtk?: number;
  /** Luck (DECISIONS #50, #52): luck × 0.2% is the chance of a critical hit and of a bonus turn per card; luck × 1.2 adds to the rare odds of rewards, the shop and level-ups. */
  luck?: number;
}

/** guard blocks the next physical hit; ward the next magic hit; aegis every hit for N rounds. */
export type StatusId = 'exposed' | 'guard' | 'ward' | 'aegis' | 'burn' | 'chill' | 'weak' | 'stun' | 'brace' | 'scatter' | 'curse' | 'harden'
  /** Regen (DECISIONS #69): heal `magnitude`% of max HP each round end; no damage cards while it lasts. Blackjack: every hit ×`magnitude` for the fight; more than 21 dealt in total and you die. */
  | 'regen' | 'blackjack'
  /** Momentum (DECISIONS #83): `magnitude` added to every hit; grows with each attack, broken by a block or a Chill. */
  | 'momentum';

export type DamageKind = 'physical' | 'magic';

/**
 * A cursed enemy's traits (DECISIONS #73), two of these: twice the HP, twice the attack, a
 * permanent shield that halves every hit, thorns that hurt the attacker, a follow-up hit after its
 * attack that no block stops.
 */
export type CursedTrait = 'hp' | 'damage' | 'shield' | 'thorns' | 'followUp';
export const CURSED_TRAITS: readonly CursedTrait[] = ['hp', 'damage', 'shield', 'thorns', 'followUp'];

/** A status instance on a combatant. `turns` ticks down at end of round; Guard and Chill are consumed instead. Stun: the player skips their turn while it lasts (turns N = N-1 skipped turns when self-applied). */
export interface Status {
  id: StatusId;
  turns: number;
  /** Guard: hits remaining. Burn: damage per tick. Others unused. */
  magnitude: number;
}

export type Target = 'self' | 'enemy';

export type Effect =
  | { type: 'damage'; targets?: 'all'; mult: number; flat?: number; hits?: number; ignoreDef?: boolean; lifesteal?: number; kind?: DamageKind }
  | { type: 'heal'; pct?: number; flat?: number }
  /** `kind: 'magic'` on a hostile status means Ward (or Aegis) blocks it like a spell. */
  | { type: 'status'; target: Target; status: StatusId; turns: number; magnitude?: number; chance?: number; kind?: DamageKind }
  /** Removes these statuses from the enemy before the hit (DECISIONS #48); `targets: 'all'` strips every living enemy. */
  | { type: 'strip'; statuses: StatusId[]; targets?: 'all' }
  /** If the card's damage leaves its target (any target, for a sweep) alive, the player loses `pct` of max HP, through any block (DECISIONS #51). */
  | { type: 'backfire'; pct: number }
  /** A card that branches (DECISIONS #69): `then` when the condition holds, else `else`. Resolved when played. */
  | { type: 'if'; cond: Condition; then: Effect[]; else: Effect[] }
  /** Play `n` more cards this turn (on top of the one this card used). */
  | { type: 'extraPlay'; n: number }
  /** Draw until the hand holds `upTo` cards. */
  | { type: 'draw'; upTo: number };

/**
 * What a branching card asks (DECISIONS #69): your HP below a share of max, the target carrying
 * a debuff (Exposed, Weak, Burn, Chill, Recovering, Curse), or a coin you call (heads or tails).
 */
export type Condition = { kind: 'selfHpBelow'; pct: number } | { kind: 'targetDebuffed' } | { kind: 'coin' }
  /** A hand of blackjack against a dealer's 16 (DECISIONS #88): two cards, hit for more; holds when you beat 16 without busting. */
  | { kind: 'blackjack' };

/** How often a tome may be played. Default: every time it is drawn. */
export type SkillUses = 'once_per_fight' | 'fleeting';

export interface Skill {
  id: SkillId;
  name: string;
  text: string;
  /** The designer's own card text (cards.json `text`), shown on the card face instead of the generated line (DECISIONS #93). */
  fixedText?: string;
  classId: ClassId | 'any';
  setId?: SetId;
  rarity: Rarity;
  effects: Effect[];
  /** The battle effect it shows (DECISIONS #59); unset = read from its effects. */
  vfx?: import('@core/vfx').VfxKind;
  /** fleeting: the tome is destroyed when played (every special tome, DECISIONS #42). once_per_fight: exhausted when played, back next fight; supported by the engine, used by no card today. */
  uses?: SkillUses;
  /** A card from the cursed pool (DECISIONS #73): never in a family, only won from a cursed enemy. */
  pool?: 'cursed';
  /** Flat damage it gains every time it lands a hit, kept for the rest of the run (#73). */
  grow?: number;
  /** Holding it, the player can take no other card (#73). */
  locksCards?: boolean;
}

export interface SkillSet {
  id: SetId;
  classId: ClassId;
  name: string;
  skills: SkillId[];
}

export interface PlayerClass {
  id: ClassId;
  name: string;
  stats: Stats;
  sets: SetId[];
}

/** What the player sees above the enemy: the move for this round. */
export type Intent =
  | { kind: 'attack'; mult: number; hits: number; ignoreDef?: boolean; drain?: boolean; dmgType?: DamageKind }
  | { kind: 'guard'; hits: number }
  | { kind: 'debuff'; status: StatusId }
  | { kind: 'buff'; status: StatusId }
  | { kind: 'stagger' };

/** The tell for the round after: a posture, not a number. */
export type Posture = 'aggressive' | 'defensive' | 'sinister' | 'charging' | 'reeling' | 'countering' | 'evasive';

export interface EnemyMove {
  id: string;
  name: string;
  intent: Intent;
  posture: Posture;
  effects: Effect[];
}

export type MoveTable =
  | { kind: 'sequence'; moves: EnemyMove[] }
  | { kind: 'weighted'; moves: { move: EnemyMove; weight: number }[] };

export interface EnemyPhase {
  /** Enter this phase when hp / maxHp <= hpBelow. */
  hpBelow: number;
  table: MoveTable;
}

export interface Enemy {
  id: EnemyId;
  name: string;
  tier: 1 | 2 | 'boss1' | 'boss2';
  archetype: 'brute' | 'armored' | 'caster' | 'swarm' | 'boss';
  stats: Stats;
  table: MoveTable;
  phases?: EnemyPhase[];
  /** Texture base for the still (default `enemy_<id>`); run-time variants point at borrowed art. */
  art?: string;
  /** Tint over the still (a ghost is pale blue). */
  tint?: number;
  /** A cursed variant's traits (DECISIONS #73). */
  cursed?: CursedTrait[];
  /** Weaknesses and habits beyond the move table (DECISIONS #83). */
  traits?: EnemyTraits;
  /** Short lines it says in battle, even with the story off (DECISIONS #83): one is picked at random. */
  barks?: { start?: string[]; rage?: string[]; death?: string[] };
  /** A roster outside the screens (DECISIONS #84): `dungeon` enemies appear only in the Treasure Dungeon. */
  set?: 'dungeon';
}

/** Enemy weaknesses and habits (DECISIONS #83). */
export interface EnemyTraits {
  /** Hit-all (sweep) damage on it is multiplied by this. */
  sweepVuln?: number;
  /** Each attack adds this much to every later hit (Momentum); a blocked hit or a Chill resets it. */
  momentum?: number;
  /** +this share of damage for each other living enemy that also has frenzy. */
  frenzy?: number;
  /** Burn ticks on it are multiplied by this. */
  burnVuln?: number;
  /** A Chill on it also leaves it Exposed for this many rounds. */
  chillExposes?: number;
  /** A Chill on it ends its Scatter (a flier brought down). */
  chillGrounds?: boolean;
}

export type Slot = 'body' | 'weapon' | 'relic';

/** Everything an item does is a modifier (ARCHITECTURE §3). Triggers arrive post-POC. */
export interface Modifier {
  stat?: Partial<Stats>;
}

export interface Item {
  id: string;
  name: string;
  slot: Slot;
  rarity: Rarity;
  text: string;
  /** Restrict to classes; omitted = any class. */
  classes?: ClassId[];
  /** Set ids this item synergises with; doubles its weight while that set is active. */
  tags?: SetId[];
  mods: Modifier[];
  /** Only this boss's loot offers it (DECISIONS #82); never a fight, chest or shop. */
  from?: EnemyId;
  /** Combat powers beyond stats (DECISIONS #82): statuses that never land on the wearer, */
  immune?: StatusId[];
  /** a chance per hit to go through Guard, Ward or Aegis, */
  pierce?: number;
  /** a once-per-fight reshuffle that costs this much gold, */
  redraw?: { gold: number };
  /** HP lost for every damaging card played (Doomsday, DECISIONS #84). */
  selfDamage?: number;
  /** What selling it pays, instead of the usual share of its price (the goat, DECISIONS #84). */
  sellPrice?: number;
}
